void append_bridge_event(const char* event, const char* detail,
                         bool sites_verified, const char* stage = nullptr,
                         const char* edge = nullptr, unsigned sequence = 0) noexcept {
    try {
        const std::string root = debug_root();
        CreateDirectoryA(root.c_str(), nullptr);
        const std::string path = root + "\\bridge.jsonl";
        FILE* file = nullptr;
        fopen_s(&file, path.c_str(), "ab");
        if (!file) return;
        if (stage) {
            std::fprintf(file,
                "{\"event\":\"startup_stage\",\"stage\":\"%s\",\"edge\":\"%s\","
                "\"detail\":\"%s\",\"thread\":%lu,\"sequence\":%u,\"uptime_ms\":%llu}\n",
                stage, edge ? edge : "unknown", detail ? detail : "",
                GetCurrentThreadId(), sequence,
                static_cast<unsigned long long>(GetTickCount64()));
            std::fflush(file);
            _commit(_fileno(file));
        } else {
            std::fprintf(file, "{\"event\":\"%s\",\"detail\":\"%s\",\"sites_verified\":%s}\n",
                         event ? event : "unknown", detail ? detail : "",
                         sites_verified ? "true" : "false");
        }
        std::fclose(file);
    } catch (...) {
    }
}

// Temporary Alt-Tab diagnostic. No extra input polling or hook installation.
bool input_focus_trace_enabled() noexcept {
    static const bool enabled = [] {
        char value[2]{};
        return GetEnvironmentVariableA("EI_RENDERER_INPUT_FOCUS_TRACE", value,
                                       sizeof(value)) == 1 && value[0] == '1';
    }();
    return enabled;
}

// Temporary startup diagnostics: fixed entry/completion and failure-only stages,
// no names/addresses from engine objects, and no scene/runtime lock acquisition.
// Normal runs do not opt in and never perform recurring diagnostic file I/O.
enum class StartupStage : unsigned {
    hooks, source_begin, source_native, source_complete, tick, world,
    terrain_capture, terrain_publish, scene_binding, scene_native, object_native,
    appearance_native, appearance, retained_seam, visual_sample, shadow, resource_native, resource_owned,
    terrain_visibility, terrain_commands, terrain_textures, terrain_renderer, shadow_prepare,
    count
};
constexpr const char* kStartupStages[]{
    "hooks", "source_begin", "source_native", "source_complete", "tick", "world",
    "terrain_capture", "terrain_publish", "scene_binding", "scene_native", "object_native",
    "appearance_native", "appearance", "retained_seam", "visual_sample", "shadow", "resource_native", "resource_owned",
    "terrain_visibility", "terrain_commands", "terrain_textures", "terrain_renderer", "shadow_prepare"
};
static_assert(sizeof(kStartupStages)/sizeof(*kStartupStages) ==
    static_cast<unsigned>(StartupStage::count));
static_assert(static_cast<unsigned>(StartupStage::count) < 32);
// The final five stages record failures only. All ordinary begin/end/failure
// records plus those independent failures fit below the unchanged hard cap.
constexpr unsigned kStartupPairedStages = static_cast<unsigned>(StartupStage::terrain_visibility);
static_assert(2 * kStartupPairedStages + static_cast<unsigned>(StartupStage::count) <= 64);
std::atomic<bool> g_startup_configured{false};
std::atomic<bool> g_startup_enabled{false};
std::atomic<unsigned> g_startup_started{0}, g_startup_failed{0}, g_startup_records{0};

void configure_startup_diagnostics() noexcept {
    if (g_startup_configured.exchange(true)) return;
    char value[2]{};
    const bool requested = GetEnvironmentVariableA("EI_RENDERER_STARTUP_TRACE", value, sizeof(value)) == 1 &&
        value[0] == '1';
    g_startup_enabled.store(requested, std::memory_order_release);
}

void startup_record(StartupStage stage, const char* edge, const char* detail) noexcept {
    const unsigned sequence = g_startup_records.fetch_add(1, std::memory_order_relaxed) + 1;
    if (sequence > 64) return;
    append_bridge_event(nullptr, detail, false, kStartupStages[static_cast<unsigned>(stage)], edge, sequence);
}

bool startup_begin(StartupStage stage) noexcept {
    if (static_cast<unsigned>(stage) >= kStartupPairedStages) return false;
    if (!g_startup_enabled.load(std::memory_order_acquire)) return false;
    const unsigned bit = 1u << static_cast<unsigned>(stage);
    if (g_startup_started.fetch_or(bit, std::memory_order_relaxed) & bit) return false;
    startup_record(stage, "begin", "entered");
    return true;
}

void startup_end(StartupStage stage, bool traced, const char* detail) noexcept {
    if (traced) startup_record(stage, "end", detail);
}

bool startup_failure(StartupStage stage, const char* detail) noexcept {
    if (g_startup_enabled.load(std::memory_order_acquire)) {
        const unsigned bit = 1u << static_cast<unsigned>(stage);
        if (!(g_startup_failed.fetch_or(bit, std::memory_order_relaxed) & bit))
            startup_record(stage, "failure", detail);
    }
    return false;
}

enum class FigureExtentContractViolation : std::uint32_t {
    none,
    missing_figure,
    missing_specific_record,
    backlink_mismatch,
    unreadable_record,
    renderer_extents_unavailable_after_submission,
    renderer_extent_publication_failed_after_submission,
    specific_extent_publication_failed_after_submission,
    caller_extent_publication_failed_after_submission,
    post_submission_fault,
};

const char* figure_extent_contract_violation_name(
    FigureExtentContractViolation violation) noexcept {
    switch (violation) {
    case FigureExtentContractViolation::none:
        return "none";
    case FigureExtentContractViolation::missing_figure:
        return "figure_extent_contract_missing_figure";
    case FigureExtentContractViolation::missing_specific_record:
        return "figure_extent_contract_missing_specific_record";
    case FigureExtentContractViolation::backlink_mismatch:
        return "figure_extent_contract_backlink_mismatch";
    case FigureExtentContractViolation::unreadable_record:
        return "figure_extent_contract_unreadable_record";
    case FigureExtentContractViolation::renderer_extents_unavailable_after_submission:
        return "figure_extent_contract_renderer_extents_unavailable_after_submission";
    case FigureExtentContractViolation::renderer_extent_publication_failed_after_submission:
        return "figure_extent_contract_renderer_extent_publication_failed_after_submission";
    case FigureExtentContractViolation::specific_extent_publication_failed_after_submission:
        return "figure_extent_contract_specific_extent_publication_failed_after_submission";
    case FigureExtentContractViolation::caller_extent_publication_failed_after_submission:
        return "figure_extent_contract_caller_extent_publication_failed_after_submission";
    case FigureExtentContractViolation::post_submission_fault:
        return "figure_extent_contract_post_submission_fault";
    }
    return "figure_extent_contract_unknown_violation";
}

[[noreturn]] void fail_figure_extent_contract(
    FigureExtentContractViolation violation) noexcept {
    const char* const detail = figure_extent_contract_violation_name(violation);
    append_bridge_event("fatal_figure_extent_contract_violation", detail,
                        EngineBridge::instance().sites_verified());
    char message[256]{};
    std::snprintf(message, sizeof(message),
                  "EID3D11 fatal figure extent contract violation: %s (0x%08lx)\n",
                  detail, static_cast<unsigned long>(kFigureExtentContractExceptionCode));
    OutputDebugStringA(message);
    EXCEPTION_RECORD record{};
    record.ExceptionCode = kFigureExtentContractExceptionCode;
    record.ExceptionFlags = EXCEPTION_NONCONTINUABLE;
    record.ExceptionAddress = _ReturnAddress();
    record.NumberParameters = 1;
    record.ExceptionInformation[0] = static_cast<ULONG_PTR>(violation);
    RaiseFailFastException(&record, nullptr, 0);
    TerminateProcess(GetCurrentProcess(), kFigureExtentContractExceptionCode);
    __assume(0);
}

