bool same_lifecycle_identity(const LifecycleIdentity& left,
                             const LifecycleIdentity& right) noexcept {
    return left.id == right.id && left.generation == right.generation &&
        left.positive_world_epoch == right.positive_world_epoch;
}

struct LifecycleIdentityLess {
    bool operator()(const LifecycleIdentity& left,
                    const LifecycleIdentity& right) const noexcept {
        if (left.id != right.id) return left.id < right.id;
        if (left.generation != right.generation)
            return left.generation < right.generation;
        return left.positive_world_epoch < right.positive_world_epoch;
    }
};

