void append_hud_test_u16(std::vector<std::uint8_t>& bytes,
                         std::uint16_t value) {
    bytes.push_back(static_cast<std::uint8_t>(value));
    bytes.push_back(static_cast<std::uint8_t>(value >> 8u));
}

void append_hud_test_u32(std::vector<std::uint8_t>& bytes,
                         std::uint32_t value) {
    for (unsigned shift = 0; shift != 32u; shift += 8u)
        bytes.push_back(static_cast<std::uint8_t>(value >> shift));
}

void append_hud_test_float(std::vector<std::uint8_t>& bytes, float value) {
    std::uint32_t bits = 0;
    std::memcpy(&bits, &value, sizeof(bits));
    append_hud_test_u32(bytes, bits);
}

std::vector<std::uint8_t> make_hud_test_interface_figure(
    std::uint32_t shape_count) {
    if (shape_count != 1u && shape_count != 8u) return {};
    std::vector<std::uint8_t> bytes;
    append_hud_test_u32(bytes, shape_count == 8u ?
        kFigureSignature8 : 0x31474946u);
    append_hud_test_u32(bytes, 1u);
    append_hud_test_u32(bytes, 1u);
    append_hud_test_u32(bytes, 4u);
    append_hud_test_u32(bytes, 6u);
    append_hud_test_u32(bytes, 4u);
    append_hud_test_u32(bytes, 0u);
    append_hud_test_u32(bytes, 0u);
    append_hud_test_u32(bytes, 0u);
    append_hud_test_u32(bytes, 0u);
    for (std::uint32_t shape = 0; shape < shape_count; ++shape) {
        append_hud_test_float(bytes, 10.0f + shape);
        append_hud_test_float(bytes, 20.0f + shape);
        append_hud_test_float(bytes, 30.0f + shape);
    }
    for (std::uint32_t shape = 0; shape < shape_count; ++shape) {
        append_hud_test_float(bytes, -1.0f - shape);
        append_hud_test_float(bytes, -2.0f - shape);
        append_hud_test_float(bytes, -3.0f - shape);
    }
    for (std::uint32_t shape = 0; shape < shape_count; ++shape) {
        append_hud_test_float(bytes, 1.0f + shape);
        append_hud_test_float(bytes, 2.0f + shape);
        append_hud_test_float(bytes, 3.0f + shape);
    }
    for (std::uint32_t shape = 0; shape < shape_count; ++shape)
        append_hud_test_float(bytes, 4.0f + shape);
    for (std::uint32_t coordinate = 0; coordinate < 3u; ++coordinate)
        for (std::uint32_t shape = 0; shape < shape_count; ++shape)
            for (std::uint32_t lane = 0; lane < 4u; ++lane)
                append_hud_test_float(
                    bytes, 100.0f * coordinate + 10.0f * shape + lane);
    for (unsigned lane = 0; lane != 4u; ++lane)
        append_hud_test_float(bytes, 0.0f);
    for (unsigned lane = 0; lane != 4u; ++lane)
        append_hud_test_float(bytes, 0.0f);
    for (unsigned lane = 0; lane != 4u; ++lane)
        append_hud_test_float(bytes, 1.0f);
    for (unsigned lane = 0; lane != 4u; ++lane)
        append_hud_test_float(bytes, 1.0f);
    for (float value : std::array<float, 8>{{0,0, 1,0, 1,1, 0,1}})
        append_hud_test_float(bytes, value);
    for (std::uint16_t index :
         std::array<std::uint16_t, 6>{{0u,1u,2u,0u,2u,3u}})
        append_hud_test_u16(bytes, index);
    for (std::uint16_t index = 0; index != 4u; ++index) {
        append_hud_test_u16(bytes, index);
        append_hud_test_u16(bytes, index);
        append_hud_test_u16(bytes, index);
    }
    return bytes;
}

