BOOL __fastcall test_hud_visual_carrier_draw(
    void* self, void*, void*) {
    auto& state = *g_hud_visual_wrapper_test;
    if (self == state.carriers[0]) return TRUE; // hidden/bind-failed before FigurePlaced
    if (self != state.carriers[1] && self != state.carriers[2]) return TRUE;
    if (state.intended_placed_calls >= state.intended_ordinals.size()) return FALSE;
    state.intended_ordinals[state.intended_placed_calls] =
        g_hud_draw.current_ordinal;
    if (g_hud_draw.current_ordinal == 1u)
        state.nested_placed_result = hook_figure_placed(
            state.placed_renderer, nullptr, state.unrelated_carrier,
            nullptr, nullptr, state.placed_material, 0xffu, nullptr);
    const std::size_t placed_index = state.intended_placed_calls++;
    state.placed_matrix_depth += 2;
    const BOOL placed_result = hook_figure_placed(
        state.placed_renderer, nullptr, self, nullptr, nullptr,
        state.placed_material, 0xffu, nullptr);
    state.intended_placed_results[placed_index] = placed_result;
    if (placed_result) state.placed_matrix_depth -= 2;
    return TRUE;
}

