bool lifecycle_read_signed_id(const void* object, std::int32_t& id) noexcept {
    if (!object) return false;
    __try {
        id = *reinterpret_cast<const std::int32_t*>(
            static_cast<const std::uint8_t*>(object) + 0x0c);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool lifecycle_read_draw_signed_id(const void* drawable, std::int32_t& id) noexcept {
    if (!drawable) return false;
    __try {
        const auto* object = *reinterpret_cast<const std::uint8_t* const*>(
            static_cast<const std::uint8_t*>(drawable) + 0x1c);
        if (!object) return false;
        id = *reinterpret_cast<const std::int32_t*>(object + 0x0c);
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

bool lifecycle_lookup_signed_id(void* self, std::int32_t id,
                                bool& present) noexcept {
    if (!self || !g_lifecycle_has_object) return false;
    __try {
        present = g_lifecycle_has_object(self, id) != FALSE;
        return true;
    } __except (EXCEPTION_EXECUTE_HANDLER) {
        return false;
    }
}

void fail_lifecycle_contract() noexcept {
    g_lifecycle_draw_oracle.store(false, std::memory_order_release);
    g_lifecycle_observing.store(false, std::memory_order_release);
    g_object_render_plans.clear();
    g_resolved_figure_geometry.clear();
    lifecycle_observer().fail_closed(LifecycleValidation::contract_fault);
}

