bool combat_ai_target(void* specific, void*& target) noexcept {
    if (!g_combat_ai_ready) return false;
    __try {
        void* logic=static_cast<std::uint8_t*>(specific)+0x980;
        using Type=int(__thiscall*)(void*);
        using Target=void*(__thiscall*)(void*);
        if (reinterpret_cast<Type>(g_visual_game_image+0x1d5e10)(logic)!=4) return false;
        target=reinterpret_cast<Target>(g_visual_game_image+0x1d5f20)(logic);
        return true;
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        combat_ui_set_status("Combat AI plates omitted: selected motivation is unavailable."); return false;
    }
}

bool combat_amounts_contract(std::uint8_t* game) noexcept {
    if (!game || !g_addon.image || g_addon.layout.effect_value_failure) return false;
    std::array<std::uint8_t,16> entry{{0x6a,0xff,0x68,0,0,0,0,0x64,0xa1,0,0,0,0,0x50,0x64,0x89}};
    write_u32(entry,3,loaded_address(game,0x32e2df));
    std::array<std::uint8_t,20> maximum{{0x55,0x8b,0xec,0x83,0xec,0x38,0xd9,0x05,0,0,0,0,
        0x8b,0xd1,0x53,0x33,0xdb,0x8b,0x82,0x9c}};
    write_u32(maximum,8,loaded_address(game,0x33b858));
    if (!exact_span(game,0x10f690,maximum)) return false;
    const auto owner=resolve_hook_entry(game+0x246b90,entry.data(),entry.size(),7);
    return owner.owner==EntryOwner::framework_chain && owner.callback==g_addon.image+g_addon.layout.effect_value_callback;
}

// The addon's perk modifier, as both discovered addon forms read it: the
// unit's level of perk subtype+7 (+0x413+perk), then entry perk*3+level-1 of
// the native perk database (0x7AF268: entries +0xC..+0x10, 0x44 bytes) and
// its modifier at +0x34. No level, or no such entry, is modifier 0.
bool combat_perk_modifier(void* unit,unsigned subtype,std::uint32_t& modifier) noexcept {
    const int perk=int(subtype)+7;
    std::uint8_t level=0; std::uintptr_t begin=0,end=0;
    modifier=0;
    if (!visual_read(unit,0x413+perk,level)) return false;
    if (!level) return true;
    if (!visual_read(g_visual_game_image,0x3af274,begin) || !visual_read(g_visual_game_image,0x3af278,end) ||
        end<begin) return false;
    const std::uintptr_t entry=std::uintptr_t(perk*3+level-1);
    return entry>=(end-begin)/0x44 || visual_read(reinterpret_cast<const void*>(begin+entry*0x44),0x34,modifier);
}

void publish_combat_amounts(void* unit,void* server,CombatUnitValue& value) noexcept {
    if (!g_combat_amounts_ready || !server || !value.effect_count) return;
    int count=0; const void* effects=nullptr; const void* catalog=nullptr; const void* catalog_end=nullptr;
    if (!visual_read(server,0x19c,count) || count!=value.effect_count || !visual_read(server,0x198,effects) || !effects ||
        !visual_read(g_visual_game_image,0x3c8510,catalog) || !visual_read(g_visual_game_image,0x3c8514,catalog_end)) return;
    const auto begin=reinterpret_cast<std::uintptr_t>(catalog),end=reinterpret_cast<std::uintptr_t>(catalog_end);
    if (!begin || end<=begin || (end-begin)%0x84) return;
    std::array<float,256> maximum{};
    // Native ordering pairs the completed client effect with the server's
    // per-instance power. A temporarily unmatched instance has no amount.
    for (unsigned i=0;i<value.effect_count;++i) {
        std::uint8_t id=0; float amount=0;
        if (!visual_read(effects,i*0x14,id) || id!=value.effects[i].id ||
            !visual_read(effects,i*0x14+8,amount) || !std::isfinite(amount)) return;
        value.effects[i].amount=amount;
        maximum[id]=(std::max)(maximum[id],amount);
    }
    std::array<float,256> multiplier{}; std::array<bool,256> calculated{};
    for (unsigned i=0;i<value.effect_count;++i) {
        auto& effect=value.effects[i]; const auto id=effect.id;
        effect.whole_amount=maximum[id]>10.f;
        if (id<=8 || id==53) {
            if (!calculated[id]) {
                unsigned subtype=0; std::uint8_t intelligence=0,base_skill=0; std::uint32_t perk_modifier=0;
                if (id>=(end-begin)/0x84 || !visual_read(reinterpret_cast<const void*>(begin+id*0x84),0x14,subtype) ||
                    subtype>7 || !visual_read(unit,0x33e,intelligence) ||
                    !visual_read(unit,subtype<=2 ? 0x40e : subtype<=4 ? 0x40f : 0x410,base_skill) ||
                    !combat_perk_modifier(unit,subtype,perk_modifier)) continue;
                const float skill_component=float(base_skill)+float(perk_modifier);
                const double skill_sum=double(skill_component)+double(int(intelligence)-25);
                if (skill_sum<INT_MIN || skill_sum>INT_MAX) continue;
                const int skill=static_cast<int>(skill_sum);
                multiplier[id]=float(double(.8f)+(double(float(skill))*30.0/120.0)/100.0);
                calculated[id]=true;
            }
            effect.amount*=multiplier[id];
        }
        effect.amount_available=std::isfinite(effect.amount);
    }
}

bool combat_cast_contract(std::uint8_t* game, std::uint8_t* addon) noexcept {
    if (!game || !addon) return false;
    // Resolve the actual current spell (including quick wand/scroll slots).
    // Never manufacture a CSpell receiver from an effect ID.
    const std::array<std::uint8_t, 94> getter{{
        0x8b,0x44,0x24,0x04,0x56,0xa9,0x00,0x00,0x00,0x80,0x74,0x45,0x8b,0x49,0x1c,0x25,0xff,0xff,0xff,0x7f,
        0x50,0xe8,0x86,0x60,0xfe,0xff,0x8b,0xf0,0x85,0xf6,0x74,0x24,0x8b,0x06,0x8b,0xce,0xff,0x50,0x30,
        0x83,0xf8,0x13,0x75,0x18,0x8b,0xce,0xe8,0x7d,0x89,0x15,0x00,0x83,0xf8,0x05,0x74,0x12,0x8b,0xce,
        0xe8,0x71,0x89,0x15,0x00,0x83,0xf8,0x08,0x74,0x06,0x33,0xc0,0x5e,0xc2,0x04,0x00,0x8b,0x46,0x44,
        0x5e,0xc2,0x04,0x00,0x8b,0x49,0x1c,0x50,0xe8,0x36,0x61,0xfe,0xff,0x5e,0xc2,0x04,0x00}};
    std::array<std::uint8_t,26> item_type{{0x8b,0x41,0x10,0x56,0x05,0xfc,0xcf,0xff,0xff,0x57,0x83,0xf8,0x05,
        0x0f,0x87,0x35,0x01,0x00,0x00,0xff,0x24,0x85,0,0,0,0}};
    write_u32(item_type,22,loaded_address(game,0x2a4380));
    std::array<std::uint8_t,24> item_dispatch{};
    const std::array<std::uint32_t,6> item_targets{{0x2a424a,0x2a4287,0x2a42c2,0x2a4335,0x2a4378,0x2a42fe}};
    for (unsigned n=0;n<item_targets.size();++n) write_u32(item_dispatch,n*4,loaded_address(game,item_targets[n]));
    if (!exact_span(game,0x14b880,getter) || !exact_span(game,0x2a4230,item_type) ||
        !exact_span(game,0x2a4380,item_dispatch) ||
        !signature(game+0x131a10,{0x56,0x8b,0xf1,0x8b,0x8e,0x40,0x02,0x00,0x00,0x8b,0x01,0xff,0x50,0x30,0x83,0xf8,0x3d}) ||
        !signature(game+0x131920,{0x56,0x8b,0xf1,0x8b,0x8e,0x40,0x02,0x00,0x00,0x8b,0x01,0xff,0x50,0x30,0x83,0xf8,0x3d}) ||
        !signature(game+0x131a5b,{0x8b,0x44,0x24,0x08,0x83,0xf8,0x08,0x73,0x12,0x8b,0xb4,0x86,0x60,0x04,0x00,0x00,
            0x85,0xf6,0x74,0x07,0x8b,0x46,0x44,0x5e,0xc2,0x04,0x00,0x33,0xc0,0x5e,0xc2,0x04,0x00}) ||
        !signature(game+0x131983,{0x8b,0x44,0x24,0x08,0x83,0xf8,0x04,0x72,0x06,0x33,0xc0,0x5e,0xc2,0x04,0x00,
            0x8b,0x84,0x86,0x50,0x04,0x00,0x00,0x5e,0xc2,0x04,0x00})) return false;

    // Stock classification remains immutable behind the addon entry hook.
    std::array<std::uint8_t,39> stock{}; stock.fill(1);
    for (unsigned id : {0u,1u,2u,3u,4u,5u,6u,7u,8u,17u,19u,25u,30u,32u,34u,36u,38u}) stock[id]=0;
    std::array<std::uint8_t,26> stock_body{{0x83,0xf8,0x26,0x77,0x12,0x33,0xc9,0x8a,0x88,0,0,0,0,
        0xff,0x24,0x8d,0,0,0,0,0xb0,0x01,0xc3,0x32,0xc0,0xc3}};
    write_u32(stock_body,9,loaded_address(game,0x28b798));
    write_u32(stock_body,16,loaded_address(game,0x28b790));
    if (!exact_span(game,0x28b776,stock_body) || !exact_span(game,0x28b798,stock)) return false;
    for (unsigned id=0;id<stock.size();++id) g_combat_stock_offensive[id]=stock[id]==0;

    // The current addon predicates and flag are discovered from their verified
    // code/owner chain, never a build-specific addon RVA.
    return addon == g_addon.image && !g_addon.layout.combat_failure;
}

bool combat_offensive_cast(void* specific, std::size_t slot_offset) noexcept {
    if (!g_combat_cast_ready) return false;
    int slot=0; if (!visual_read(specific,slot_offset,slot)) return false;
    __try {
        using GetSpell = void* (__thiscall*)(void*,int);
        void* spell=reinterpret_cast<GetSpell>(g_visual_game_image+0x14b880)(specific,slot);
        if (!spell) return false;
        std::uint16_t type=0; std::uint8_t selfcast=0;
        const auto& combat=g_addon.layout.combat;
        if (!visual_read(spell,0x1a,type) || !visual_read(g_addon.image,combat.selfcast_enabled,selfcast)) return false;
        return (type<g_combat_stock_offensive.size() && g_combat_stock_offensive[type]) ||
            (type<combat.offensive.size() && combat.offensive[type]) ||
            (selfcast && type<combat.selfcast.size() && combat.selfcast[type]);
    } __except(EXCEPTION_EXECUTE_HANDLER) {
        combat_ui_set_status("Offensive caster plates omitted: current spell is unavailable."); return false;
    }
}

void* combat_server_unit(std::int32_t id) noexcept {
    auto* const image = g_visual_game_image;
    auto* const world = image + 0x3aff60;
    void* table = nullptr; int mode = 0, loaded = 0;
    const void* begin = nullptr; const void* end = nullptr;
    if (!g_combat_server_ready || !visual_read(world, 0, table) || table != image + 0x33f928 ||
        !visual_read(world, 0x138, mode) || mode != 1 || !visual_read(world, 0x15c, loaded) || !loaded ||
        !visual_read(world, 0x12d74, begin) || !visual_read(world, 0x12d78, end) || !begin ||
        reinterpret_cast<std::uintptr_t>(end) <= reinterpret_cast<std::uintptr_t>(begin)) return nullptr;
    void* object = nullptr;
    __try {
        using Lookup = void* (__thiscall*)(void*, std::int32_t);
        object = reinterpret_cast<Lookup>(image + 0x15fb00)(world, id);
    } __except(EXCEPTION_EXECUTE_HANDLER) { return nullptr; }
    return object;
}

void publish_combat_catalog() noexcept {
    if (g_combat_catalog_ready) return;
    std::uint32_t variant=0;
    if(!read_hud_overlay_variant(variant))return;
    const void* begin = nullptr; const void* end = nullptr;
    if (!visual_read(g_visual_game_image, 0x3c8510, begin) || !visual_read(g_visual_game_image, 0x3c8514, end)) return;
    const auto first = reinterpret_cast<std::uintptr_t>(begin), last = reinterpret_cast<std::uintptr_t>(end);
    if (!first || last <= first || (last-first) % 0x84 || (last-first) / 0x84 > 65536) return;
    std::array<CombatEffectDefinition, 256> catalog{};
    const auto count = (std::min)(std::size_t{256}, (last-first)/0x84);
    for (std::size_t i = 0; i < count; ++i) {
        auto* record = reinterpret_cast<const void*>(first+i*0x84);
        const char* name = nullptr;
        if (!visual_read(record, 0x60, catalog[i].icon) || !visual_read(record, 4, name) || !name) return;
        for (std::size_t n = 0; n+1 < catalog[i].name.size(); ++n) {
            if (!visual_read(name, n, catalog[i].name[n])) return;
            if (!catalog[i].name[n]) break;
        }
        catalog[i].valid = catalog[i].name[0] != 0;
        catalog[i].hd_icon = variant != 0;
        // Display policy follows the spell descriptions; cast-targeting
        // predicates are not buff/debuff polarity. Players can override it.
        for (const auto* harmful:{"stench","stun","weak","feeblemind","slow","firewall","litnwall","acid_fog"})
            if (_stricmp(catalog[i].name.data(),harmful)==0) catalog[i].debuff=true;
    }
    combat_ui_publish_catalog(catalog); g_combat_catalog_ready = true;
}

void publish_combat_unit(void* object, std::int32_t id, std::uint64_t incarnation,bool force) noexcept {
    if (!g_hud_active_screen || !g_visual_game_image || !incarnation || (!force && !combat_ui_has_output())) return;
    if (!g_combat_values_checked) {
        g_combat_values_ready = combat_values_contract(g_visual_game_image);
        g_combat_server_ready = combat_server_contract(g_visual_game_image);
        g_combat_portraits_ready = widescreen_interface_owned();
        g_combat_cast_ready = combat_cast_contract(g_visual_game_image,g_hud_visual_addon_image);
        g_combat_ai_ready = combat_ai_contract(g_visual_game_image);
        g_combat_amounts_ready = combat_amounts_contract(g_visual_game_image);
        g_combat_values_checked = true;
        combat_ui_set_status(!g_combat_values_ready ? "Combat UI unavailable: effect/health contract mismatch." :
            !g_combat_server_ready ? "Portrait effects ready; combat healthplate contract is unavailable." :
            !g_combat_portraits_ready ? "Combat plates ready; portrait area contract mismatch." :
            !g_combat_cast_ready ? "Attack plates ready; offensive spell contract mismatch." :
            !g_combat_ai_ready ? "Combat AI plates unavailable: selected motivation contract mismatch." :
            "Active combat AI / attack / offensive cast participants; game-owned health and effect timers.");
        append_bridge_event("combat_ui_contract", g_combat_values_ready ? "effects_ready" : "effects_rejected", true);
        if (!g_combat_amounts_ready)
            append_bridge_event("combat_effect_values_omitted",g_addon.layout.effect_value_failure ?
                g_addon.layout.effect_value_failure : "Live spell-value owner mismatch.",true);
    }
    if (!g_combat_values_ready) return;
    publish_combat_catalog();
    std::int16_t health = 0, maximum = 0; std::uint32_t dead = 0; int count = 0; const void* effects = nullptr;
    if (!visual_read(object, 0x274, dead) || !visual_read(object, 0x17e, health) || !visual_read(object, 0x180, maximum) ||
        !visual_read(object, 0x19c, count) || count < 0 || count > 255 ||
        !visual_read(object, 0x198, effects) || (count && !effects)) {
        combat_ui_retire_unit(id); combat_ui_set_status("Combat UI omitted: invalid completed unit values."); return;
    }
    CombatUnitValue value; value.id = id; value.incarnation = incarnation;
    value.health = health; value.maximum_health = maximum; value.effect_count = static_cast<std::uint16_t>(count);
    value.dead = dead != 0;
    for (int i = 0; i < count; ++i) {
        if (!visual_read(effects, static_cast<std::size_t>(i)*0x14, value.effects[i].id) ||
            !visual_read(effects, static_cast<std::size_t>(i)*0x14+4, value.effects[i].ticks)) {
            combat_ui_retire_unit(id); return;
        }
    }
    void* server = combat_server_unit(id); void* specific = nullptr; void* owner = nullptr; void* table = nullptr;
    publish_combat_amounts(object,server,value);
    if (!value.dead && health>0 && server && visual_read(server, 0x240, specific) && specific &&
        visual_read(specific, 0, table) && table == g_visual_game_image+0x33ef38 &&
        visual_read(specific, 0x1c, owner) && owner == server) {
        unsigned targets=0;
        const auto add_target=[&](void* target) {
            std::int32_t target_id=0;
            if (!target || !visual_read(target,0,table) || table!=g_visual_game_image+kObjectSupportedPrimaryVtableRva ||
                !visual_read(target,0x0c,target_id) || !target_id) return;
            for (unsigned n=0;n<targets;++n) if (value.attack_targets[n]==target_id) return;
            value.attack_targets[targets++]=target_id;
        };
        for (const auto offset : {std::size_t{0x190}, std::size_t{0x1b4}}) {
            int command=9;
            if (!visual_read(specific,offset,command) ||
                !(command==3 || ((command==4 || command==5) && combat_offensive_cast(specific,offset+4)))) continue;
            // Intent belongs to the actor even when the target is a point or a
            // non-unit object. Current and queued unit targets may differ.
            value.attacking=true;
            void* target=nullptr;
            if (command!=4 && visual_read(specific,offset+8,target)) add_target(target);
        }
        void* target=nullptr;
        if (combat_ai_target(specific,target)) { value.attacking=true; add_target(target); }
    }
    combat_ui_publish_unit(value);
}

void publish_combat_portraits() noexcept {
    std::array<HudPortraitSlot,32> slots{};
    std::array<CombatPortraitAnchor,32> anchors{};
    const auto count=widescreen_hud_portrait_slots(slots.data(),slots.size());
    static ULONGLONG next_values=0;
    const auto now=GetTickCount64();
    const bool refresh=now>=next_values;
    if(refresh)next_values=now+66;
    std::size_t published=0;
    for(std::size_t i=0;i<count;++i) {
        const auto& slot=slots[i];
        if(refresh) {
            const auto resource=retained_visual_scene().visual_resource(slot.id);
            publish_combat_unit(const_cast<void*>(slot.unit),slot.id,resource.serial);
        }
        const auto& b=slot.bounds;
        anchors[published++]={slot.id,b.left,b.top,b.left+b.width,b.top+b.height};
    }
    combat_ui_publish_portraits(anchors.data(),published);
}

bool character_pane_live_contract(
    std::uint8_t* image, std::uint8_t* addon) noexcept {
    if (addon || widescreen_interface_owned()
            ? !character_pane_widescreen_chain(image,addon)
            : !character_pane_native_chain(image)) return false;
    const std::array<std::uint32_t, kCharacterPaneHookCount - 1u> rvas{{
        kCharacterPaneDrawTextRva,
        kCharacterPaneInterfaceInitRva, kCharacterPaneInterfaceFiniRva}};
    for (std::size_t index = 0; index < rvas.size(); ++index)
        if (!hook_entry_usable(image + rvas[index], kCharacterPaneEntryStock[index].data(),
                               kCharacterPanePatchBytes, kCharacterPanePatchBytes))
            return false;
    const std::array<std::pair<std::uint32_t,
                              std::array<std::uint8_t, 3>>, 3> calls{{
        {0x001fdc24u, {{0xff,0x51,0x44}}},
        {0x001fdc81u, {{0xff,0x51,0x68}}},
        {0x001fdb87u, {{0xff,0x52,0x14}}},
    }};
    for (const auto& call : calls)
        if (std::memcmp(image + call.first, call.second.data(),
                        call.second.size()) != 0)
            return false;
    if (std::memcmp(image + 0x001fdbd4u, "\xff\x51\x14", 3u) != 0 ||
        !relative_call_targets(
            image + 0x002463e5u, image + 0x001fdc00u) ||
        !relative_call_targets(
            image + 0x00246b18u, image + 0x001fdc60u) ||
        std::memcmp(image + 0x001fdf94u,
                    "\x83\xc4\x38\xc2\x18\x00", 6u) != 0)
        return false;
    return true;
}

bool install_character_pane_text_hooks_from_chain(
    std::uint8_t* image, std::uint8_t* addon) noexcept {
    g_character_pane_install_detail = "invalid_game_or_already_installed";
    if (!image || g_character_pane_hooks_installed) return false;
    if (!character_pane_live_contract(image, addon)) {
        g_character_pane_install_detail = "live_text_transaction_mismatch";
        return false;
    }
    const auto patches = character_pane_entry_patches(image);
    for (std::size_t index = 0; index < patches.size(); ++index) {
        std::memcpy(g_character_pane_original[index].data(),
                    patches[index].entry, kCharacterPanePatchBytes);
        g_character_pane_trampolines[index] = nullptr;
        if (index == 0u && (addon || widescreen_interface_owned())) continue;
        const auto* stock = index == 0u ? kCharacterPaneDrawStock
            : kCharacterPaneEntryStock[index - 1u].data();
        g_character_pane_trampolines[index] = make_entry_forwarder(
            patches[index].entry, stock,
            kCharacterPanePatchBytes, kCharacterPanePatchBytes);
        if (!g_character_pane_trampolines[index]) {
            for (void*& trampoline : g_character_pane_trampolines) {
                if (trampoline) VirtualFree(trampoline, 0, MEM_RELEASE);
                trampoline = nullptr;
            }
            g_character_pane_install_detail = "trampoline_allocation_failed";
            return false;
        }
    }
    g_character_pane_draw = reinterpret_cast<CharacterPaneDrawFn>(widescreen_interface_owned()
        ? const_cast<void*>(widescreen_info_draw_entry())
        : addon ? static_cast<void*>(addon+g_addon.layout.pane.draw_start)
                : g_character_pane_trampolines[0]);
    g_character_pane_text_surface_local = addon || widescreen_interface_owned();
    g_character_pane_draw_text = reinterpret_cast<CharacterPaneDrawTextFn>(
        g_character_pane_trampolines[1]);
    g_character_pane_interface_init =
        reinterpret_cast<CharacterPaneInterfaceInitFn>(
            g_character_pane_trampolines[2]);
    g_character_pane_interface_fini =
        reinterpret_cast<CharacterPaneInterfaceFiniFn>(
            g_character_pane_trampolines[3]);
    g_character_pane_virtual_to_screen =
        reinterpret_cast<CharacterPaneRectTransformFn>(
            image + kCharacterPaneVirtualToScreenRva);
    g_character_pane_screen_to_virtual =
        reinterpret_cast<CharacterPaneSizeTransformFn>(
            image + kCharacterPaneScreenToVirtualRva);
    g_character_pane_game_image = image;

    std::size_t patched = 0;
    for (; patched < patches.size(); ++patched) {
        DWORD previous = 0;
        if (!VirtualProtect(
                patches[patched].entry, kCharacterPanePatchBytes,
                PAGE_EXECUTE_READWRITE, &previous))
            break;
        const bool wrote = write_relative_jump(
            patches[patched].entry, patches[patched].replacement);
        if (wrote)
            std::memset(patches[patched].entry + 5u, 0x90,
                        kCharacterPanePatchBytes - 5u);
        DWORD ignored = 0;
        VirtualProtect(patches[patched].entry, kCharacterPanePatchBytes,
                       previous, &ignored);
        FlushInstructionCache(
            GetCurrentProcess(), patches[patched].entry,
            kCharacterPanePatchBytes);
        if (!wrote) break;
    }
    if (patched != patches.size()) {
        bool restored = true;
        while (patched) {
            --patched;
            restored = restore_inline_entry(
                           patches[patched].entry,
                           g_character_pane_original[patched].data(),
                           kCharacterPanePatchBytes) && restored;
        }
        if (!restored) {
            g_character_pane_hooks_installed = true;
            g_character_pane_install_detail =
                "patch_transaction_rollback_failed";
            return false;
        }
        for (void*& trampoline : g_character_pane_trampolines) {
            if (trampoline) VirtualFree(trampoline, 0, MEM_RELEASE);
            trampoline = nullptr;
        }
        g_character_pane_draw = nullptr;
        g_character_pane_draw_text = nullptr;
        g_character_pane_interface_init = nullptr;
        g_character_pane_interface_fini = nullptr;
        g_character_pane_virtual_to_screen = nullptr;
        g_character_pane_screen_to_virtual = nullptr;
        g_character_pane_game_image = nullptr;
        g_character_pane_install_detail = "patch_transaction_rejected";
        return false;
    }
    g_character_pane_hooks_installed = true;
    InterlockedExchange(&g_character_pane_failure_reported, 0);
    g_character_pane_install_detail = widescreen_interface_owned()
        ? "verified_owned_widescreen_pane_text_transaction"
        : addon ? "verified_supported_pane_text_transaction"
                : "verified_native_pane_text_transaction";
    return true;
}

bool install_character_pane_text_hooks(std::uint8_t* image) noexcept {
    auto* addon = find_addon_module();
    if (!widescreen_interface_owned() && addon && g_addon.layout.pane_failure) {
        g_character_pane_install_detail = g_addon.layout.pane_failure;
        return false;
    }
    const bool ready=install_character_pane_text_hooks_from_chain(image,widescreen_interface_owned() ? nullptr : addon);
    if (ready) {
        auto* site=image+0x246aa7;
        const auto hook=reinterpret_cast<const void*>(&hook_character_pane_effects);
        const bool contract=signature(image+0x246a9f,{0x83,0xf8,0x03,0x75,0x08,0x57,0x8b,0xcb}) &&
            signature(site,{0xe8,0xe4,0x00,0x00,0x00}) && relative_call_fits(site,hook);
        DWORD protection=0;
        if (contract && VirtualProtect(site,5,PAGE_EXECUTE_READWRITE,&protection)) {
            std::memcpy(g_character_pane_effects_original.data(),site,5);
            g_character_pane_effects_installed=write_relative_call(site,hook);
            DWORD ignored=0; VirtualProtect(site,5,protection,&ignored); FlushInstructionCache(GetCurrentProcess(),site,5);
        }
        if (!g_character_pane_effects_installed)
            append_bridge_event("character_spell_list_omitted","Spell-list call contract mismatch.",true);
    }
    return ready;
}

bool uninstall_character_pane_text_hooks() noexcept {
    if (!g_character_pane_hooks_installed) return true;
    if (!g_character_pane_game_image) return false;
    if (g_character_pane_effects_installed) {
        auto* site=g_character_pane_game_image+0x246aa7;
        if (!relative_call_targets(site,reinterpret_cast<const void*>(&hook_character_pane_effects)) ||
            !restore_inline_entry(site,g_character_pane_effects_original.data(),5)) return false;
        g_character_pane_effects_installed=false;
    }
    const auto patches = character_pane_entry_patches(
        g_character_pane_game_image);
    for (std::size_t index = 0; index < patches.size(); ++index)
        if (relative_jump_target(patches[index].entry) !=
                patches[index].replacement &&
            std::memcmp(patches[index].entry,
                        g_character_pane_original[index].data(),
                        kCharacterPanePatchBytes) != 0)
            return false;
    for (std::size_t remaining = patches.size(); remaining; --remaining) {
        const std::size_t index = remaining - 1u;
        if (relative_jump_target(patches[index].entry) ==
                patches[index].replacement &&
            !restore_inline_entry(
                patches[index].entry,
                g_character_pane_original[index].data(),
                kCharacterPanePatchBytes))
            return false;
    }
    for (void*& trampoline : g_character_pane_trampolines) {
        if (trampoline) VirtualFree(trampoline, 0, MEM_RELEASE);
        trampoline = nullptr;
    }
    retire_character_pane_text();
    g_character_pane_text_stack = {};
    g_character_pane_draw = nullptr;
    g_character_pane_draw_text = nullptr;
    g_character_pane_interface_init = nullptr;
    g_character_pane_interface_fini = nullptr;
    g_character_pane_virtual_to_screen = nullptr;
    g_character_pane_screen_to_virtual = nullptr;
    g_character_pane_game_image = nullptr;
    g_character_pane_hooks_installed = false;
    g_character_pane_text_surface_local = false;
    InterlockedExchange(&g_character_pane_failure_reported, 0);
    return true;
}

// ---- Chat phrase text (CI3DChat::NewPhrase / Draw2D) ----
// NewPhrase creates one CI3DSurface per wrapped line and fills it once:
// GetDC, Clear (a GDI fill of the whole surface with its color key),
// DrawText per color segment, ReleaseDC. Draw2D then presents every live
// line each frame through CI3DSurface::Draw. Each owned ReleaseDC publishes
// a retained frame for that surface; blits inside Draw2D present it. The
// input line (RedrawChatPhrase, which also draws a GDI caret) stays legacy.
volatile LONG g_chat_failure_reported = 0;

void report_chat_text_failure(CharacterPaneTextFailure failure) noexcept {
    if (InterlockedCompareExchange(&g_chat_failure_reported, 1, 0) != 0)
        return;
    append_bridge_event("chat_owned_text_omitted",
                        character_pane_text_failure_name(failure), true);
}

void __fastcall hook_chat_new_phrase(
    void* self, void*, const char* phrase, int order) {
    const std::size_t index = g_character_pane_text_stack.depth++;
    const bool tracked = index < kCharacterPaneMaximumDepth;
    if (tracked) {
        auto& invocation = g_character_pane_text_stack.values[index];
        invocation = {};
        bool parent_armed = false;
        for (std::size_t parent = 0; parent < index; ++parent)
            parent_armed = parent_armed ||
                g_character_pane_text_stack.values[parent].armed;
        invocation.chat = true;
        invocation.armed = !parent_armed &&
            !g_character_pane_text.frame_claimed() &&
            g_character_pane_font_generation.load(
                std::memory_order_acquire) != 0;
    }
    __try {
        g_chat_new_phrase(self, phrase, order);
    } __finally {
        if (tracked) {
            auto& invocation = g_character_pane_text_stack.values[index];
            if (invocation.claimed) {
                // GetDC without its ReleaseDC: the line shows nothing.
                g_character_pane_text.abort_frame();
                g_chat_text_frames.retire(invocation.surface_id);
                report_chat_text_failure(
                    CharacterPaneTextFailure::dc_transaction);
            }
            invocation = {};
        }
        if (g_character_pane_text_stack.depth)
            --g_character_pane_text_stack.depth;
    }
}

void __fastcall hook_chat_draw2d(void* self, void*) {
    ++g_chat_draw_depth;
    __try {
        g_chat_draw2d(self);
    } __finally {
        --g_chat_draw_depth;
    }
}

constexpr std::uint8_t kChatNewPhraseStock[kChatNewPhrasePatchBytes] = {
    0x6a,0xff,0x68,0x24,0x8f,0x72,0x00};
constexpr std::uint8_t kChatDraw2DStock[kChatDraw2DPatchBytes] = {
    0x53,0x8b,0xd9,0x56,0x8b,0x83,0x48,0x01,0x00,0x00};

bool chat_live_contract(const std::uint8_t* image) noexcept {
    return hook_entry_usable(image + kChatNewPhraseRva, kChatNewPhraseStock,
                             kChatNewPhrasePatchBytes, kChatNewPhrasePatchBytes) &&
        hook_entry_usable(image + kChatDraw2DRva, kChatDraw2DStock,
                          kChatDraw2DPatchBytes, kChatDraw2DPatchBytes) &&
        // NewPhrase line fill: GetDC, Clear, DrawText x2, ReleaseDC.
        relative_call_targets(image + 0x001e2fa0u, image + 0x001fdc00u) &&
        relative_call_targets(image + 0x001e2fa7u, image + 0x001fe2f0u) &&
        relative_call_targets(image + 0x001e306au,
                              image + kCharacterPaneDrawTextRva) &&
        relative_call_targets(image + 0x001e319au,
                              image + kCharacterPaneDrawTextRva) &&
        relative_call_targets(image + 0x001e31a1u, image + 0x001fdc60u) &&
        // Clear is the stock GDI FillSolidRect body.
        std::memcmp(image + 0x001fe2f0u, "\x83\xec\x20\x56\x8b\xf1", 6u) == 0 &&
        // Draw2D: virtual CI3DSurface::Draw per line, then CI3DObject::Draw2D.
        std::memcmp(image + 0x001e2a06u, "\x8b\x01\xff\x10", 4u) == 0 &&
        relative_call_targets(image + 0x001e2a1du, image + 0x001fecc0u);
}

bool write_chat_entry(std::uint8_t* entry, std::size_t bytes,
                      const void* replacement) noexcept {
    DWORD previous = 0;
    if (!VirtualProtect(entry, bytes, PAGE_EXECUTE_READWRITE, &previous))
        return false;
    const bool wrote = write_relative_jump(entry, replacement);
    if (wrote) std::memset(entry + 5u, 0x90, bytes - 5u);
    DWORD ignored = 0;
    VirtualProtect(entry, bytes, previous, &ignored);
    FlushInstructionCache(GetCurrentProcess(), entry, bytes);
    return wrote;
}

void release_chat_trampolines() noexcept {
    for (void*& trampoline : g_chat_trampolines) {
        if (trampoline) VirtualFree(trampoline, 0, MEM_RELEASE);
        trampoline = nullptr;
    }
    g_chat_new_phrase = nullptr;
    g_chat_draw2d = nullptr;
}

// Requires the character pane text transaction (DrawText, GetDC/ReleaseDC
// and Blt admission, font generation) to be installed first.
bool install_chat_text_hooks(std::uint8_t* image) noexcept {
    g_chat_install_detail = "pane_text_inactive_or_already_installed";
    if (!image || g_chat_hooks_installed || !g_character_pane_hooks_installed ||
        image != g_character_pane_game_image)
        return false;
    if (!chat_live_contract(image)) {
        g_chat_install_detail = "live_chat_producer_mismatch";
        return false;
    }
    auto* new_phrase = image + kChatNewPhraseRva;
    auto* draw2d = image + kChatDraw2DRva;
    std::memcpy(g_chat_new_phrase_original.data(), new_phrase,
                kChatNewPhrasePatchBytes);
    std::memcpy(g_chat_draw2d_original.data(), draw2d, kChatDraw2DPatchBytes);
    g_chat_trampolines[0] = make_entry_forwarder(
        new_phrase, kChatNewPhraseStock, kChatNewPhrasePatchBytes, kChatNewPhrasePatchBytes);
    g_chat_trampolines[1] = make_entry_forwarder(
        draw2d, kChatDraw2DStock, kChatDraw2DPatchBytes, kChatDraw2DPatchBytes);
    if (!g_chat_trampolines[0] || !g_chat_trampolines[1]) {
        release_chat_trampolines();
        g_chat_install_detail = "trampoline_allocation_failed";
        return false;
    }
    g_chat_new_phrase = reinterpret_cast<ChatNewPhraseFn>(g_chat_trampolines[0]);
    g_chat_draw2d = reinterpret_cast<ChatDraw2DFn>(g_chat_trampolines[1]);
    if (!write_chat_entry(new_phrase, kChatNewPhrasePatchBytes,
                          reinterpret_cast<const void*>(&hook_chat_new_phrase))) {
        release_chat_trampolines();
        g_chat_install_detail = "patch_transaction_rejected";
        return false;
    }
    if (!write_chat_entry(draw2d, kChatDraw2DPatchBytes,
                          reinterpret_cast<const void*>(&hook_chat_draw2d))) {
        if (!restore_forwarding_hook(new_phrase,g_chat_new_phrase_original.data(),
                kChatNewPhrasePatchBytes,reinterpret_cast<const void*>(&hook_chat_new_phrase),false,"chat.install_rollback")) {
            g_chat_hooks_installed = true;
            g_chat_install_detail = "patch_transaction_rollback_failed";
            return false;
        }
        release_chat_trampolines();
        g_chat_install_detail = "patch_transaction_rejected";
        return false;
    }
    g_chat_text_frames.clear();
    g_chat_text_ui_epoch = 0;
    g_chat_draw_depth = 0;
    g_chat_hooks_installed = true;
    InterlockedExchange(&g_chat_failure_reported, 0);
    g_chat_install_detail = "verified_chat_phrase_text_transaction";
    return true;
}

bool uninstall_chat_text_hooks() noexcept {
    if (!g_chat_hooks_installed) return true;
    if (!g_character_pane_game_image) return false;
    auto* new_phrase = g_character_pane_game_image + kChatNewPhraseRva;
    auto* draw2d = g_character_pane_game_image + kChatDraw2DRva;
    if (!restore_forwarding_hook(new_phrase,g_chat_new_phrase_original.data(),
            kChatNewPhrasePatchBytes,reinterpret_cast<const void*>(&hook_chat_new_phrase),false,"chat.new_phrase") ||
        !restore_forwarding_hook(draw2d,g_chat_draw2d_original.data(),
            kChatDraw2DPatchBytes,reinterpret_cast<const void*>(&hook_chat_draw2d),false,"chat.draw2d")) return false;
    release_chat_trampolines();
    g_chat_text_frames.clear();
    g_chat_text_ui_epoch = 0;
    g_chat_hooks_installed = false;
    InterlockedExchange(&g_chat_failure_reported, 0);
    return true;
}

enum class TerrainSetLightPatchResult {
    installed,
    rejected,
    rollback_failed,
};

template <typename PatchCall, typename RestoreCall>
TerrainSetLightPatchResult patch_terrain_set_light_calls_transaction(
    const std::array<std::uint8_t*, 2>& calls,
    const void* stock_target, const void* hook,
    std::array<std::array<std::uint8_t, kTerrainSetLightCallBytes>, 2>& originals,
    PatchCall patch_call, RestoreCall restore_call) {
    // Validate the whole caller set before touching either site. The two
    // fingerprinted calls are one ownership transaction.
    for (const auto* call : calls)
        if (!relative_call_targets(call, stock_target))
            return TerrainSetLightPatchResult::rejected;
    for (std::size_t index = 0; index < calls.size(); ++index)
        std::memcpy(originals[index].data(), calls[index],
                    kTerrainSetLightCallBytes);
    std::size_t patched = 0;
    for (; patched < calls.size(); ++patched)
        if (!patch_call(calls[patched], hook)) break;
    if (patched == calls.size()) return TerrainSetLightPatchResult::installed;
    bool restored = true;
    for (std::size_t index = 0; index < patched; ++index)
        restored = restore_call(calls[index], originals[index].data()) &&
            restored;
    return restored ? TerrainSetLightPatchResult::rejected
                    : TerrainSetLightPatchResult::rollback_failed;
}

template <typename RestoreCall>
bool restore_terrain_set_light_calls_if_owned(
    const std::array<std::uint8_t*, 2>& calls, const void* hook,
    const std::array<
        std::array<std::uint8_t, kTerrainSetLightCallBytes>, 2>& originals,
    RestoreCall restore_call) {
    bool restored = true;
    for (std::size_t index = 0; index < calls.size(); ++index)
        if (relative_call_targets(calls[index], hook))
            restored = restore_call(calls[index], originals[index].data()) &&
                restored;
    return restored;
}

bool install_native_geometry_hook(std::uint8_t* image) {
    if (!native_tl_requested()) return false;
    auto* entry = image + kNativeGeometryEntryRva;
    auto* animated_texture_entry = image + kFigureAnimatedTextureEntryRva;
    auto* string_construct_entry = image + kEngineStringConstructRva;
    auto* string_assign_entry = image + kEngineStringAssignRangeRva;
    auto* string_destroy_entry = image + kEngineStringDestroyRva;
    static const std::uint8_t kStock[] = {0x55,0x8b,0xec,0x83,0xec,0x14};
    static_assert(sizeof(kStock) == kNativeGeometryPatchBytes);
    if (!hook_entry_usable(entry, kStock, sizeof(kStock), kNativeGeometryPatchBytes) ||
        !signature(animated_texture_entry, {0x56,0x8b,0xf1,0x57,0x8b,0x7e,0x1c}) ||
        !signature(string_construct_entry, {0x8b,0x54,0x24,0x04,0x8b,0xc1,0x33,0xc9}) ||
        !signature(string_assign_entry, {0x83,0xec,0x0c,0x53,0x55}) ||
        !signature(string_destroy_entry, {0x8b,0x01,0x8b,0x49,0x08,0x2b,0xc8}))
        return false;

    auto* trampoline = make_entry_forwarder(entry, kStock, sizeof(kStock),
                                            kNativeGeometryPatchBytes);
    if (!trampoline) return false;
    std::memcpy(g_native_geometry_original.data(), entry, kNativeGeometryPatchBytes);

    DWORD entry_protection = 0;
    if (!VirtualProtect(entry, kNativeGeometryPatchBytes, PAGE_EXECUTE_READWRITE,
                        &entry_protection)) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        return false;
    }
    const bool patched = write_relative_jump(entry, reinterpret_cast<const void*>(&hook_native_geometry));
    if (patched) entry[5] = 0x90;
    DWORD ignored = 0;
    VirtualProtect(entry, kNativeGeometryPatchBytes, entry_protection, &ignored);
    FlushInstructionCache(GetCurrentProcess(), entry, kNativeGeometryPatchBytes);
    if (!patched) {
        VirtualFree(trampoline, 0, MEM_RELEASE);
        return false;
    }
    g_native_geometry_trampoline = trampoline;
    g_native_geometry = reinterpret_cast<NativeGeometryFn>(trampoline);
    g_figure_animated_texture = reinterpret_cast<FigureAnimatedTextureFn>(
        animated_texture_entry);
    g_engine_string_construct = reinterpret_cast<EngineStringConstructFn>(
        string_construct_entry);
    g_engine_string_assign_range = reinterpret_cast<EngineStringAssignRangeFn>(
        string_assign_entry);
    g_engine_string_destroy = reinterpret_cast<EngineStringDestroyFn>(
        string_destroy_entry);
    g_native_geometry_installed = true;
    return true;
}

void uninstall_native_geometry_hook(std::uint8_t* image) {
    if (!g_native_geometry_installed || !image) return;
    auto* entry = image + kNativeGeometryEntryRva;
    bool owns_entry = false;
    if (entry[0] == 0xe9) {
        std::int32_t relative = 0;
        std::memcpy(&relative, entry + 1, sizeof(relative));
        owns_entry = entry + 5 + relative ==
            reinterpret_cast<const std::uint8_t*>(&hook_native_geometry);
    }
    if (owns_entry) {
        DWORD protection = 0;
        if (VirtualProtect(entry, kNativeGeometryPatchBytes, PAGE_EXECUTE_READWRITE,
                           &protection)) {
            std::memcpy(entry, g_native_geometry_original.data(), kNativeGeometryPatchBytes);
            DWORD ignored = 0;
            VirtualProtect(entry, kNativeGeometryPatchBytes, protection, &ignored);
            FlushInstructionCache(GetCurrentProcess(), entry, kNativeGeometryPatchBytes);
        }
    }
    if (g_native_geometry_trampoline)
        VirtualFree(g_native_geometry_trampoline, 0, MEM_RELEASE);
    g_native_geometry_trampoline = nullptr;
    g_native_geometry = nullptr;
    g_figure_animated_texture = nullptr;
    g_engine_string_construct = nullptr;
    g_engine_string_assign_range = nullptr;
    g_engine_string_destroy = nullptr;
    g_native_geometry_installed = false;
}

bool restore_inline_entry(std::uint8_t* entry, const std::uint8_t* original,
                          std::size_t bytes) noexcept {
    if (!entry || !original || !bytes) return false;
#ifdef EID3D11_TESTING
    if(entry==g_test_restore_fail_entry)return false;
#endif
    DWORD protection = 0;
    if (!VirtualProtect(entry, bytes, PAGE_EXECUTE_READWRITE, &protection)) return false;
    std::memcpy(entry, original, bytes);
    DWORD ignored = 0;
    const bool protection_restored =
        VirtualProtect(entry, bytes, protection, &ignored) != FALSE;
    FlushInstructionCache(GetCurrentProcess(), entry, bytes);
    return protection_restored && std::memcmp(entry, original, bytes) == 0;
}

bool restore_forwarding_hook(std::uint8_t* entry,const std::uint8_t* original,
    std::size_t bytes,const void* hook,bool call,const char* owner) noexcept {
    const bool restored=restore_owned_hook(entry,original,bytes,hook,call,&restore_inline_entry);
    if(!restored) {
        static const char* last=nullptr;
        if(last!=owner)append_bridge_event("hook_teardown_pending",owner,true);
        last=owner;
    }
    return restored;
}

bool executable_address(const void* address) noexcept {
    MEMORY_BASIC_INFORMATION memory{};
    if (!address || !VirtualQuery(address, &memory, sizeof(memory)) ||
        memory.State != MEM_COMMIT || (memory.Protect & PAGE_GUARD) != 0)
        return false;
    const DWORD protection = memory.Protect & 0xffu;
    return protection == PAGE_EXECUTE || protection == PAGE_EXECUTE_READ ||
        protection == PAGE_EXECUTE_READWRITE ||
        protection == PAGE_EXECUTE_WRITECOPY;
}

// This is a finite patch contract for the supported pair of images. It is
// deliberately not a detour decoder: an unknown active chain rejects the set.
constexpr std::size_t kVisualProducerEntries = 29;
constexpr std::size_t kVisualProducerPatches = kVisualProducerEntries + 3;
struct VisualProducerPatch {
    std::uint8_t* entry;
    const void* hook;
    std::size_t size;
    std::array<std::uint8_t, 10> expected;
    std::size_t relative_call = SIZE_MAX;
    bool call_site = false;
};
std::array<void*, kVisualProducerEntries> g_visual_trampolines{};
// False for an addon hook-framework dispatcher used as the forwarding target.
std::array<bool, kVisualProducerEntries> g_visual_trampoline_owned{};
std::array<std::array<std::uint8_t, 10>, kVisualProducerPatches> g_visual_original{};
bool g_visual_hooks_installed = false;
const char* g_visual_install_detail = "not_attempted";
std::uint8_t* g_generated_mmp_route_addon = nullptr;
std::uint8_t g_generated_mmp_route_original = 0;
bool g_generated_mmp_route_changed = false;
#ifdef EID3D11_TESTING
int g_visual_test_patch_failure = -1;
bool g_visual_test_route_postwrite_failure = false;
#endif

bool write_generated_mmp_route(std::uint8_t* route, std::uint8_t expected,
                               std::uint8_t replacement) noexcept {
    if (!route || *route != expected) return false;
    DWORD protection = 0;
    if (!VirtualProtect(route, 1, PAGE_READWRITE, &protection)) return false;
    bool wrote = false;
    if (*route == expected) {
        *route = replacement;
        MemoryBarrier();
        wrote = *route == replacement;
    }
    DWORD ignored = 0;
    const bool restored =
        VirtualProtect(route, 1, protection, &ignored) != FALSE;
    return wrote && restored;
}

bool install_generated_mmp_memory_route(std::uint8_t* addon) noexcept {
    if (g_generated_mmp_route_addon ||
        !generated_mmp_route_live_contract(addon)) return false;
    auto* const route = addon + g_addon.layout.visual.route;
    g_generated_mmp_route_addon = addon;
    g_generated_mmp_route_original = *route;
    g_generated_mmp_route_changed = false;
    if (*route == kGeneratedMmpMemoryRoute) return true;
    const bool installed = write_generated_mmp_route(
        route, g_generated_mmp_route_original, kGeneratedMmpMemoryRoute);
    g_generated_mmp_route_changed = *route == kGeneratedMmpMemoryRoute;
    if (!installed && !g_generated_mmp_route_changed) {
        g_generated_mmp_route_addon = nullptr;
        g_generated_mmp_route_original = 0;
    }
    return installed;
}

bool restore_generated_mmp_route() noexcept {
    if (!g_generated_mmp_route_addon) return true;
    auto* const route =
        g_generated_mmp_route_addon + g_addon.layout.visual.route;
    if (*route != g_generated_mmp_route_original) {
        if (*route != kGeneratedMmpMemoryRoute ||
            !g_generated_mmp_route_changed ||
            !write_generated_mmp_route(route, kGeneratedMmpMemoryRoute,
                                       g_generated_mmp_route_original))
            return false;
    }
    g_generated_mmp_route_addon = nullptr;
    g_generated_mmp_route_original = 0;
    g_generated_mmp_route_changed = false;
    return true;
}

