bool bridge_consume_hud_atlas_window(
    IDirectDrawSurface7* surface, const void* lock_caller,
    HudAtlasMutationWindow& window) noexcept {
    window = {};
    if (!g_hud_atlas_hooks_installed || !surface) return false;
    const HudAtlasProducerContext context = g_hud_atlas_producer;
    bool eligible = false;
    if (g_addon_hud_atlas_lock_pending) {
        g_addon_hud_atlas_lock_pending = false;
        eligible = context.kind == HudAtlasProducerKind::addon &&
            !context.consumed;
    } else if (context.kind == HudAtlasProducerKind::stock &&
               !context.consumed &&
               g_hud_atlas_game_image &&
               reinterpret_cast<std::uintptr_t>(lock_caller) ==
                   reinterpret_cast<std::uintptr_t>(g_hud_atlas_game_image) +
                       kStockHudAtlasSurfaceLockReturnRva) {
        eligible = true;
    }
    if (eligible) g_hud_atlas_producer.consumed = true;
    if (!eligible ||
        current_texture_surface(context.destination_texture) != surface)
        return false;
    window = context.window;
    return true;
}

bool bridge_begin_character_pane_getdc(
    IDirectDrawSurface7* surface, const void* caller,
    std::uint64_t surface_id, std::uint32_t width,
    std::uint32_t height, float raster_scale) noexcept {
    auto* invocation = current_character_pane_text_invocation();
    const bool caller_matches = g_character_pane_game_image &&
        reinterpret_cast<std::uintptr_t>(caller) ==
            reinterpret_cast<std::uintptr_t>(g_character_pane_game_image) +
                kCharacterPaneGetDcReturnRva;
#ifdef EID3D11_TESTING
    const bool admitted_caller = caller_matches ||
        g_character_pane_proxy_test_mode;
#else
    const bool admitted_caller = caller_matches;
#endif
    if (!invocation || !invocation->armed || invocation->claimed ||
        invocation->released ||
        (!invocation->chat && invocation->surface != surface) ||
        !surface || !surface_id || !admitted_caller)
        return false;
    const std::uint64_t generation =
        g_character_pane_font_generation.load(std::memory_order_acquire);
    if (!generation) return false;
    g_character_pane_text.initialize_fonts(generation);
    if (invocation->chat) invocation->surface = surface;
    invocation->surface_id = surface_id;
    invocation->claimed = true;
    g_character_pane_text.begin_frame(width, height, raster_scale);
    return true;
}

bool bridge_finish_character_pane_releasedc(
    IDirectDrawSurface7* surface, const void* caller,
    std::uint64_t surface_id, std::uint64_t surface_generation) noexcept {
    auto* invocation = current_character_pane_text_invocation();
    const bool caller_matches = g_character_pane_game_image &&
        reinterpret_cast<std::uintptr_t>(caller) ==
            reinterpret_cast<std::uintptr_t>(g_character_pane_game_image) +
                kCharacterPaneReleaseDcReturnRva;
#ifdef EID3D11_TESTING
    const bool admitted_caller = caller_matches ||
        g_character_pane_proxy_test_mode;
#else
    const bool admitted_caller = caller_matches;
#endif
    if (!invocation || !invocation->claimed || invocation->released ||
        invocation->surface != surface ||
        invocation->surface_id != surface_id)
        return false;
    invocation->released = true;
    g_character_pane_text.finish_dc(admitted_caller);
    if (invocation->chat) {
        // Publish this line now; NewPhrase may claim the next line surface.
        const CharacterPaneTextFailure failure =
            g_character_pane_text.failure();
        CharacterPaneTextFrame frame{};
        const bool published = g_character_pane_text.take(frame) &&
            g_chat_text_frames.publish(
                surface_id, surface_generation, std::move(frame));
        g_character_pane_text.abort_frame();
        if (published && !g_chat_text_ui_epoch) {
            std::uint64_t epoch = g_character_pane_next_ui_epoch.fetch_add(
                1u, std::memory_order_acq_rel);
            if (!epoch)
                epoch = g_character_pane_next_ui_epoch.fetch_add(
                    1u, std::memory_order_acq_rel);
            g_chat_text_ui_epoch = epoch;
        }
        if (!published) {
            g_chat_text_frames.retire(surface_id);
            report_chat_text_failure(
                failure == CharacterPaneTextFailure::none
                    ? CharacterPaneTextFailure::dc_transaction : failure);
        }
        invocation->surface = nullptr;
        invocation->surface_id = 0;
        invocation->claimed = false;
        invocation->released = false;
    }
    return true;
}

void bridge_retire_owned_text_surface(std::uint64_t surface_id) noexcept {
    g_chat_text_frames.retire(surface_id);
}

bool bridge_consume_character_pane_blt(
    std::uint64_t source_id, const void* caller,
    const RECT& destination, const RECT* source_rect,
    Renderer& renderer, HRESULT& result,
    std::uint64_t source_generation) noexcept {
    result = DD_OK;
    if (!source_id) return false;
    const bool pane_source = g_character_pane_text_publication.valid &&
        g_character_pane_text_publication.surface_id == source_id;
    if (!pane_source && (!g_chat_draw_depth || !g_chat_text_frames.size()))
        return false;
    const std::uintptr_t return_address =
        reinterpret_cast<std::uintptr_t>(caller);
    const std::uintptr_t image =
        reinterpret_cast<std::uintptr_t>(g_character_pane_game_image);
    const bool caller_matches = g_character_pane_game_image &&
        (return_address == image + kCharacterPaneKeyedBltReturnRva ||
         return_address == image + kCharacterPaneUnkeyedBltReturnRva);
#ifdef EID3D11_TESTING
    const bool admitted_caller = caller_matches ||
        g_character_pane_proxy_test_mode;
#else
    const bool admitted_caller = caller_matches;
#endif
    if (!admitted_caller)
        return false;
    if (!pane_source) {
        // Chat line presented by CI3DChat::Draw2D through CI3DSurface::Draw.
        const CharacterPaneTextFrame* frame = nullptr;
        const auto lookup =
            g_chat_text_frames.find(source_id, source_generation, frame);
        if (lookup == RetainedOwnedTextFrames::Lookup::absent) return false;
        if (lookup == RetainedOwnedTextFrames::Lookup::stale ||
            !g_chat_text_ui_epoch) {
            // Written outside the owned DC after publication: omit the line.
            report_chat_text_failure(CharacterPaneTextFailure::dc_transaction);
            return true;
        }
        result = renderer.queue_character_pane_text(
            *frame, g_chat_text_ui_epoch, g_bridge_frame_serial,
            destination, source_rect);
        if (FAILED(result))
            report_chat_text_failure(CharacterPaneTextFailure::submission);
        return true;
    }
    CharacterPaneTextPublication publication =
        std::move(g_character_pane_text_publication);
    g_character_pane_text_publication = {};
    if (publication.ui_epoch != g_character_pane_ui_epoch ||
        publication.frame_serial != g_bridge_frame_serial ||
        !publication.complete) {
        report_character_pane_text_failure(
            publication.failure == CharacterPaneTextFailure::none
                ? CharacterPaneTextFailure::dc_transaction
                : publication.failure);
        return true;
    }
    result = renderer.queue_character_pane_text(
        publication.frame, publication.ui_epoch,
        publication.frame_serial, destination, source_rect);
    if (FAILED(result))
        report_character_pane_text_failure(
            CharacterPaneTextFailure::submission);
    return true;
}

bool bridge_character_pane_text_epoch_current(
    std::uint64_t ui_epoch, std::uint64_t frame_serial) noexcept {
    return g_character_pane_hooks_installed && ui_epoch &&
        (ui_epoch == g_character_pane_ui_epoch ||
         ui_epoch == g_chat_text_ui_epoch) &&
        frame_serial == g_bridge_frame_serial;
}

