        // insufficient: exercise the actual completed new-intent producers.
        const auto previous_mode=state.update_mode;
        state.update_mode=0;
        const auto completed=hook_visual_unit_update(state.object,nullptr,0);
        state.update_mode=previous_mode;
        if (!completed) return FALSE;
