        if (read_log()!=shared) return false;

        auto visual_values=std::make_shared<RetainedVisualFrame>();
        visual_values->entities.reserve(kObjectPlanOmissionDiagnosticLimit);
        auto assembly=std::make_shared<VisualAssemblyAsset>();
