bool bridge_test_arm_character_pane_proxy_transaction(
    IDirectDrawSurface7* surface) noexcept {
    if (!surface || g_character_pane_text_stack.depth != 0u ||
        (g_character_pane_hooks_installed &&
         !g_character_pane_proxy_test_mode)) return false;
    if (!g_character_pane_proxy_test_mode) {
        g_character_pane_hooks_installed = true;
        g_character_pane_proxy_test_mode = true;
        g_character_pane_game_image = reinterpret_cast<std::uint8_t*>(1u);
        g_character_pane_font_generation.store(1u);
        g_character_pane_text.initialize_fonts(1u);
    }
    next_character_pane_ui_epoch();
    g_character_pane_text_stack.depth = 1u;
    auto& invocation = g_character_pane_text_stack.values[0];
    invocation = {};
    invocation.surface = surface;
    invocation.ui_epoch = g_character_pane_ui_epoch;
    invocation.armed = true;
    return true;
}

bool bridge_test_draw_character_pane_proxy_text(HFONT font) noexcept {
    if (!g_character_pane_proxy_test_mode ||
        !g_character_pane_text.frame_claimed()) return false;
    const RECT rectangle{2, 2, 30, 30};
    bool height_valid = false;
    const int height = g_character_pane_text.draw(
        font, 0u, "HP", rectangle, DT_LEFT, RGB(255, 255, 255),
        true, height_valid);
    return height_valid && height > 0 &&
        g_character_pane_text.failure() ==
            CharacterPaneTextFailure::none;
}

bool bridge_test_publish_character_pane_proxy_transaction() noexcept {
    if (!g_character_pane_proxy_test_mode ||
        g_character_pane_text_stack.depth != 1u)
        return false;
    auto& invocation = g_character_pane_text_stack.values[0];
    if (!invocation.claimed) return false;
    publish_character_pane_text(invocation);
    invocation = {};
    g_character_pane_text_stack.depth = 0u;
    return g_character_pane_text_publication.valid;
}

bool bridge_test_character_pane_published_first_quad(
    RECT& destination) noexcept {
    destination = {};
    if (!g_character_pane_proxy_test_mode ||
        !g_character_pane_text_publication.valid ||
        !g_character_pane_text_publication.complete ||
        g_character_pane_text_publication.frame.quads.empty())
        return false;
    destination =
        g_character_pane_text_publication.frame.quads.front().destination;
    return true;
}

void bridge_test_disarm_character_pane_proxy_transaction() noexcept {
    g_character_pane_text.abort_frame();
    g_character_pane_text_publication = {};
    g_character_pane_text_stack = {};
    g_character_pane_font_generation.store(0u);
    g_character_pane_ui_epoch = 0u;
    g_character_pane_game_image = nullptr;
    g_character_pane_proxy_test_mode = false;
    g_character_pane_hooks_installed = false;
}

