int __fastcall test_character_pane_draw_text_original(
    void*, void*, const char*, const RECT*, int, COLORREF, int, BOOL) {
    ++g_character_pane_wrapper_test->text_original_calls;
    return 37;
}

void __fastcall test_character_pane_rect_widescreen(
    void* receiver, void*, RECT* rectangle) {
    auto& state = *g_character_pane_wrapper_test;
    ++state.rect_transform_calls;
    state.rect_transform_nonnull_receiver =
        state.rect_transform_nonnull_receiver || receiver != nullptr;
    if (receiver && rectangle) OffsetRect(rectangle, 40, 0);
}
void __fastcall test_character_pane_size_identity(void*, void*, SIZE*) {}

