bool bridge_test_object_plan_mutation_retirement() noexcept {
    try {
        g_object_render_plans.clear();
        g_resolved_figure_geometry.clear();
        lifecycle_observer().reset();
        lifecycle_observer().record_positive_bulk_reset();
        lifecycle_observer().record_inserted(148);
        LifecycleIdentity identity{};
        if (!lifecycle_observer().active_identity(148, identity) ||
            identity.positive_world_epoch == 0)
            return false;
        alignas(void*) std::array<std::uint8_t, 0xe0> owner{};
        *reinterpret_cast<std::int32_t*>(owner.data() + 0x0c) = 148;
        ObjectRenderPlan plan{};
        plan.identity = identity;
        plan.owner = owner.data();
        plan.generation = 9;
        g_object_render_plans.emplace(identity, plan);
        ResolvedFigureGeometry selector{};
        selector.lifecycle = identity;
        selector.lifecycle_valid = true;
        g_resolved_figure_geometry.emplace(
            reinterpret_cast<void*>(0x1234u), selector);

        // Both exact figure add/remove hooks retire through this production
        // owner invalidation boundary after their original mutation succeeds.
        invalidate_object_render_plan_owner(owner.data());
        if (!g_object_render_plans.empty() ||
            !g_resolved_figure_geometry.empty())
            return false;

        g_object_render_plans.emplace(identity, plan);
        // The state-sensitive complection hook reaches the same boundary only
        // after observing an actual revision-vector change.
        invalidate_object_render_plan_owner(owner.data());
        const bool retired = g_object_render_plans.empty();
        lifecycle_observer().reset();
        return retired;
    } catch (...) {
        g_object_render_plans.clear();
        g_resolved_figure_geometry.clear();
        lifecycle_observer().reset();
        return false;
    }
}

bool bridge_test_object_plan_extent_publication(
    void* specific, const RECT* values, std::size_t count) noexcept {
    if (!specific || (count && !values)) return false;
    RECT merged{};
    bool have_extents = false;
    for (std::size_t index = 0; index < count; ++index)
        if (!merge_object_plan_extents(
                merged, values[index], true, have_extents))
            return false;
    return have_extents && publish_object_plan_extents(specific, merged);
}

