BOOL __fastcall shared_lighting_test_world(void* renderer, void*) {
    return publish_native_world_lighting(renderer) == FigureFallbackReason::none &&
        publish_native_world_lighting(renderer) == FigureFallbackReason::none;
}

bool bridge_test_shared_world_lighting_policy() noexcept {
    if (g_world_draw_depth) return false;
    std::array<std::uint8_t, 0x30> renderer{};
    std::array<std::uint8_t, 0x30> scene_renderer{};
    std::array<std::uint8_t, 0xe0> sunlight{};
    const std::array<float, 3> direction{0.25f, -0.5f, 0.75f};
    const void* sunlight_pointer = sunlight.data();
    const void* scene_renderer_pointer = scene_renderer.data();
    std::memcpy(renderer.data() + 0x1c, &sunlight_pointer,
                sizeof(sunlight_pointer));
    std::memcpy(renderer.data() + kWorldFigureRendererSceneRendererOffset,
                &scene_renderer_pointer, sizeof(scene_renderer_pointer));
    std::memcpy(sunlight.data() + 0xd4, direction.data(),
                sizeof(direction));
    const std::uint32_t ambient = 0xff1f3f5fu;
    const std::array<float,3> diffuse{0.7f,0.4f,0.2f};
    std::memcpy(renderer.data()+0x18,&ambient,sizeof(ambient));
    std::memcpy(sunlight.data()+0x98,diffuse.data(),sizeof(diffuse));
    NativeWorldLighting rejected{};
    if (snapshot_native_world_lighting(scene_renderer.data(), rejected) ||
        !world_figure_renderer_owns_scene_renderer(
            renderer.data(), scene_renderer.data()) ||
        world_figure_renderer_owns_scene_renderer(
            renderer.data(), reinterpret_cast<void*>(0x1234u)))
        return false;
    NativeWorldLighting first{};
    if (!snapshot_native_world_lighting(renderer.data(), first)) return false;

    // The environment owns no per-object light ingress. Mutating an unrelated
    // legacy array cannot affect the next snapshot.
    std::array<std::uint8_t, 64> legacy_point_lights{};
    legacy_point_lights.fill(0x7f);
    NativeWorldLighting second{};
    if (!snapshot_native_world_lighting(renderer.data(), second)) return false;
    if (!(first.ambient == std::array<float, 4>{31/255.0f,63/255.0f,95/255.0f,1} &&
        first.sunlight_diffuse == std::array<float, 4>{0.7f,0.4f,0.2f,1} &&
        first.sunlight_direction ==
            std::array<float, 4>{-0.25f, 0.5f, -0.75f, 0.0f} &&
        std::memcmp(&first, &second, sizeof(first)) == 0)) return false;

    struct Capture { std::array<NativeWorldLighting,4> values{};std::size_t count=0; } capture;
    const auto saved_sink = g_native_sink_world_lighting;
    void* const saved_context = g_native_sink_context;
    const auto saved_world_draw = g_world_draw;
    const bool saved_sky_enabled = g_owned_sky_enabled;
    const auto saved_lighting = g_native_world_lighting_frame;
    auto saved_terrain = std::move(g_owned_terrain_frame);
    const auto saved_world_serial = g_owned_terrain_world_serial;
    const auto present_serial = g_bridge_frame_serial;
    const auto saved_profile_begin = g_world_profile_begin;
    const bool saved_profiling = g_bridge_sample.active;
    g_bridge_sample.active = false;
    g_owned_terrain_frame = {};
    g_native_sink_context = &capture;
    g_native_sink_world_lighting = [](void* value,const NativeWorldLighting& lighting) {
        auto& output = *static_cast<Capture*>(value);
        if (output.count == output.values.size()) return false;
        output.values[output.count++] = lighting;
        return true;
    };
    g_world_draw = reinterpret_cast<ScenePhaseFn>(&shared_lighting_test_world);
    // This fixture provides a lighting owner, without a module/sky-hook image.
    // The owned-sky rejection contract has its own production-path fixture.
    g_owned_sky_enabled = false;
    bool passed = hook_world_draw(renderer.data(),nullptr) != FALSE && capture.count == 1 &&
        std::memcmp(&capture.values[0],&first,sizeof(first)) == 0;
    const std::uint32_t next_ambient = 0xffd09030u;
    const std::array<float,3> next_diffuse{0.2f,0.3f,0.8f};
    std::memcpy(renderer.data()+0x18,&next_ambient,sizeof(next_ambient));
    std::memcpy(sunlight.data()+0x98,next_diffuse.data(),sizeof(next_diffuse));
    passed = hook_world_draw(renderer.data(),nullptr) != FALSE && capture.count == 2 &&
        capture.values[1].ambient == std::array<float,4>{208/255.0f,144/255.0f,48/255.0f,1} &&
        capture.values[1].sunlight_diffuse == std::array<float,4>{0.2f,0.3f,0.8f,1} &&
        g_bridge_frame_serial == present_serial && !g_native_world_lighting_frame.sampled && passed;
    const float invalid = (std::numeric_limits<float>::quiet_NaN)();
    std::memcpy(sunlight.data()+0x98,&invalid,sizeof(invalid));
    passed = hook_world_draw(renderer.data(),nullptr) == FALSE && capture.count == 2 &&
        !g_native_world_lighting_frame.sampled && passed;
    g_native_sink_world_lighting = saved_sink;
    g_native_sink_context = saved_context;
    g_world_draw = saved_world_draw;
    g_owned_sky_enabled = saved_sky_enabled;
    g_native_world_lighting_frame = saved_lighting;
    g_owned_terrain_frame = std::move(saved_terrain);
    g_owned_terrain_world_serial = saved_world_serial;
    g_world_profile_begin = saved_profile_begin;
    g_bridge_sample.active = saved_profiling;
    return passed;
}

void retained_source_chain_test_target() {}

bool bridge_test_retained_source_hook_roundtrip() noexcept {
    if (g_retained_source_hooks_installed) return false;
    auto* image = static_cast<std::uint8_t*>(VirtualAlloc(
        nullptr, kExpectedImageSize, MEM_RESERVE | MEM_COMMIT,
        PAGE_EXECUTE_READWRITE));
    if (!image) return false;
    const std::array<std::uint8_t, kRetainedMainLoaderPatchBytes> main_loader{
        0x64,0xa1,0x00,0x00,0x00,0x00,0x6a,0xff,
        0x68,0x18,0x65,0x72,0x00};
    constexpr std::uint32_t legacy_fresh_owner_rva = 0x00195480;
    const std::array<std::uint8_t, 13> legacy_fresh_owner{
        0x64,0xa1,0x00,0x00,0x00,0x00,0x6a,0xff,
        0x68,0x58,0x64,0x72,0x00};
    const std::array<std::uint8_t, kRetainedSecondaryOwnerPatchBytes>
        secondary_owner{
            0x55,0x8b,0x6c,0x24,0x08,0x56,0x8b,0xf1,0x57,0x33,0xff};
    const std::array<std::uint8_t, kRetainedCommonParserPatchBytes> parser{
        0x6a,0xff,0x68,0x40,0x65,0x72,0x00};
    const std::array<std::uint8_t, kRetainedAdmissionPatchBytes> admission{
        0x55,0x8b,0xec,0x6a,0xff,0x68,0x30,0x61,0x72,0x00};
    std::memcpy(image + legacy_fresh_owner_rva, legacy_fresh_owner.data(),
                legacy_fresh_owner.size());
    std::memcpy(image + kRetainedSecondaryOwnerEntryRva,
                secondary_owner.data(), secondary_owner.size());
    std::memcpy(image + kRetainedCommonParserEntryRva, parser.data(),
                parser.size());
    std::memcpy(image + kRetainedAdmissionEntryRva, admission.data(),
                admission.size());
    // The former fresh-map wrapper plus every other valid source seam is not
    // enough: the shared fresh/save loader itself must match and be patched.
    const bool legacy_only_rejected = !install_retained_source_hooks(image);
    std::memcpy(image + kRetainedMainLoaderEntryRva, main_loader.data(),
                main_loader.size());
    const bool installed = install_retained_source_hooks(image) &&
        std::memcmp(image + legacy_fresh_owner_rva,
                    legacy_fresh_owner.data(),
                    legacy_fresh_owner.size()) == 0 &&
        relative_jump_target(image + kRetainedMainLoaderEntryRva) ==
            reinterpret_cast<const void*>(&hook_retained_main_loader) &&
        relative_jump_target(image + kRetainedSecondaryOwnerEntryRva) ==
            reinterpret_cast<const void*>(&hook_retained_secondary_owner) &&
        relative_jump_target(image + kRetainedCommonParserEntryRva) ==
            reinterpret_cast<const void*>(&hook_retained_common_parser) &&
        relative_jump_target(image + kRetainedAdmissionEntryRva) ==
            reinterpret_cast<const void*>(&hook_retained_admission);
    const bool removed = installed && uninstall_retained_source_hooks(image);
    const bool restored = removed &&
        std::memcmp(image + legacy_fresh_owner_rva,
                    legacy_fresh_owner.data(),
                    legacy_fresh_owner.size()) == 0 &&
        std::memcmp(image + kRetainedMainLoaderEntryRva, main_loader.data(),
                    main_loader.size()) == 0 &&
        std::memcmp(image + kRetainedSecondaryOwnerEntryRva,
                    secondary_owner.data(), secondary_owner.size()) == 0 &&
        std::memcmp(image + kRetainedCommonParserEntryRva, parser.data(),
                    parser.size()) == 0 &&
        std::memcmp(image + kRetainedAdmissionEntryRva, admission.data(),
                    admission.size()) == 0;

    // A raw jump at a source entry is not a verified addon hook-framework
    // chain: the transaction rejects and leaves every entry unchanged.
    auto* raw_main_entry = image + kRetainedMainLoaderEntryRva;
    const bool raw_encoded = write_relative_jump(
        raw_main_entry,
        reinterpret_cast<const void*>(&retained_source_chain_test_target));
    std::array<std::uint8_t, kRetainedMainLoaderPatchBytes> raw_original{};
    std::memcpy(raw_original.data(), raw_main_entry, raw_original.size());
    const bool raw_rejected = raw_encoded &&
        !install_retained_source_hooks(image) && !g_retained_source_hooks_installed &&
        std::memcmp(raw_main_entry, raw_original.data(), raw_original.size()) == 0 &&
        std::memcmp(image + kRetainedSecondaryOwnerEntryRva,
                    secondary_owner.data(), secondary_owner.size()) == 0;
    std::memcpy(raw_main_entry, main_loader.data(), main_loader.size());
    const bool legacy_owner_untouched =
        std::memcmp(image + legacy_fresh_owner_rva,
                    legacy_fresh_owner.data(),
                    legacy_fresh_owner.size()) == 0;
    if (legacy_only_rejected && restored && raw_rejected && legacy_owner_untouched)
        VirtualFree(image, 0, MEM_RELEASE);
    return legacy_only_rejected && restored && raw_rejected && legacy_owner_untouched;
}

