const char* figure_fallback_reason_name(FigureFallbackReason reason) noexcept {
    switch (reason) {
    case FigureFallbackReason::none: return "none";
    case FigureFallbackReason::unavailable: return "unavailable";
    case FigureFallbackReason::hidden: return "hidden";
    case FigureFallbackReason::renderer_state: return "renderer state";
    case FigureFallbackReason::transform: return "transform";
    case FigureFallbackReason::material: return "material";
    case FigureFallbackReason::light_array: return "light array";
    case FigureFallbackReason::morph_data: return "morph data";
    case FigureFallbackReason::geometry: return "geometry";
    case FigureFallbackReason::metadata: return "metadata";
    case FigureFallbackReason::state_write: return "state write";
    case FigureFallbackReason::direct_submit: return "direct submit";
    case FigureFallbackReason::exception: return "exception";
    default: return "unknown";
    }
}

