void bridge_profile_begin_frame() {
    if (!bridge_profile_enabled()) g_latest_bridge_profile.owned_visual={};
    ++g_bridge_frame_serial;
    g_world_draw_completion = {};
    if (g_character_pane_hooks_installed)
        next_character_pane_ui_epoch();
    if (g_resolved_figure_geometry.size() > 8192) {
        for (auto item = g_resolved_figure_geometry.begin();
             item != g_resolved_figure_geometry.end();) {
            if (g_bridge_frame_serial - item->second.last_seen_frame > 600)
                item = g_resolved_figure_geometry.erase(item);
            else
                ++item;
        }
    }
    if (!bridge_profile_enabled() || g_bridge_sample.active) return;
    const auto now = bridge_now();
    const auto next_frame = g_bridge_sample.frame + 1;
    g_bridge_sample = {};
    g_scene_partition = {};
    g_bridge_sample.frame = next_frame;
    g_bridge_sample.frame_begin = now;
    g_bridge_sample.begin_interval_ticks = g_previous_frame_begin ? now - g_previous_frame_begin : 0;
    g_bridge_sample.terrain_animation_owned_updates = static_cast<std::uint64_t>(
        InterlockedExchange64(&g_pending_terrain_animation_owned_updates, 0));
    g_bridge_sample.terrain_animation_fallback_updates = static_cast<std::uint64_t>(
        InterlockedExchange64(&g_pending_terrain_animation_fallback_updates, 0));
    g_bridge_sample.terrain_wave_sectors = static_cast<std::uint64_t>(
        InterlockedExchange64(&g_pending_terrain_wave_sectors, 0));
    g_bridge_sample.terrain_animated_tile_updates = static_cast<std::uint64_t>(
        InterlockedExchange64(&g_pending_terrain_animated_tile_updates, 0));
    g_previous_frame_begin = now;
    g_bridge_sample.active = true;
    if (g_world_draw_depth) {
        g_world_profile_begin = now;
        g_bridge_sample.world_draw_calls = 1;
    }
    if (g_scene_3d_depth) {
        g_scene_3d_profile_begin = now;
        g_bridge_sample.scene_3d_calls = 1;
        g_bridge_sample.scene_partition_valid = false;
    }
}

void bridge_profile_end_frame() {
    g_world_draw_completion = {};
    if (!bridge_profile_enabled() || !g_bridge_sample.active) return;
    if (g_scene_partition.active) {
        invalidate_scene_partition();
        g_scene_partition = {};
    }
    write_bridge_sample(bridge_now());
    g_bridge_sample.active = false;
}

bool bridge_outer_frame_timing_supported() noexcept {
    return g_outer_frame_timing_hooks_installed;
}

void bridge_set_outer_frame_timing_active(bool active) noexcept {
    g_outer_frame_timing = {};
    visual_unit_update_profile_reset();
    g_native_tick_original_profile_active = false;
    g_native_tick_owned_current = NativeTickOwnedCallback::count;
    g_native_tick_owned_begin = 0;
    g_native_tick_owned_depth = 0;
    g_native_tick_owned_pause_depth = 0;
    InterlockedExchange(&g_outer_frame_timing_active,
                        active && g_outer_frame_timing_hooks_installed ? 1 : 0);
}

PostEngineSurfaceTimingToken bridge_post_engine_surface_timing_begin(
    PostEngineSurfaceTimingKind kind) noexcept {
    PostEngineSurfaceTimingToken token{};
    token.kind = kind;
    if (!outer_frame_timing_active() ||
        !g_outer_frame_timing.frame_ended ||
        g_outer_frame_timing.end_frame_return <= 0)
        return token;
    const auto index = static_cast<std::size_t>(kind);
    if (index >= g_outer_frame_timing.post_engine_surface_depths.size()) {
        g_outer_frame_timing.invalid = true;
        return token;
    }
    if (kind != PostEngineSurfaceTimingKind::proxy &&
        !g_outer_frame_timing.post_engine_surface_depths[
            static_cast<std::size_t>(PostEngineSurfaceTimingKind::proxy)])
        return token;
    token.tracked = true;
    token.owner = ++g_outer_frame_timing.post_engine_surface_depths[index] == 1;
    if (!token.owner) return token;
    token.inside_flush = kind == PostEngineSurfaceTimingKind::completed_surface &&
        g_outer_frame_timing.post_engine_surface_depths[
            static_cast<std::size_t>(PostEngineSurfaceTimingKind::flush)] != 0;
    if (kind == PostEngineSurfaceTimingKind::flush)
        token.excluded_at_begin =
            g_outer_frame_timing.post_engine_completed_surface_inside_flush_ticks;
    token.begin = bridge_now();
    if (token.begin <= 0) g_outer_frame_timing.invalid = true;
    return token;
}

void bridge_post_engine_surface_timing_end(
    PostEngineSurfaceTimingToken token, std::uint64_t amount) noexcept {
    if (!token.tracked) return;
    const auto index = static_cast<std::size_t>(token.kind);
    if (index >= g_outer_frame_timing.post_engine_surface_depths.size() ||
        !g_outer_frame_timing.post_engine_surface_depths[index]) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    --g_outer_frame_timing.post_engine_surface_depths[index];
    if (!token.owner) return;
    const auto end = bridge_now();
    if (token.begin <= 0 || end < token.begin) {
        g_outer_frame_timing.invalid = true;
        return;
    }
    auto ticks = end - token.begin;
    if (token.kind == PostEngineSurfaceTimingKind::flush) {
        const auto excluded =
            g_outer_frame_timing.post_engine_completed_surface_inside_flush_ticks -
            token.excluded_at_begin;
        if (excluded < 0 || excluded > ticks) {
            g_outer_frame_timing.invalid = true;
            ticks = 0;
        } else {
            ticks -= excluded;
        }
    }
    switch (token.kind) {
    case PostEngineSurfaceTimingKind::proxy:
        if (std::any_of(
                g_outer_frame_timing.post_engine_surface_depths.begin() + 1,
                g_outer_frame_timing.post_engine_surface_depths.end(),
                [](std::uint32_t depth) { return depth != 0; }))
            g_outer_frame_timing.invalid = true;
        g_outer_frame_timing.post_engine_surface_proxy_ticks += ticks;
        ++g_outer_frame_timing.post_engine_surface_proxy_calls;
        break;
    case PostEngineSurfaceTimingKind::flush:
        g_outer_frame_timing.post_engine_surface_flush_ticks += ticks;
        ++g_outer_frame_timing.post_engine_surface_flush_calls;
        break;
    case PostEngineSurfaceTimingKind::cpu_rect:
        g_outer_frame_timing.post_engine_surface_cpu_rect_ticks += ticks;
        ++g_outer_frame_timing.post_engine_surface_cpu_rect_calls;
        g_outer_frame_timing.post_engine_surface_cpu_rect_pixels += amount;
        break;
    case PostEngineSurfaceTimingKind::completed_surface:
        g_outer_frame_timing.post_engine_completed_surface_ticks += ticks;
        ++g_outer_frame_timing.post_engine_completed_surface_calls;
        g_outer_frame_timing.post_engine_completed_surface_bytes += amount;
        if (token.inside_flush)
            g_outer_frame_timing.post_engine_completed_surface_inside_flush_ticks +=
                ticks;
        break;
    }
}

void bridge_post_engine_surface_material_group_scan() noexcept {
    if (!outer_frame_timing_active() ||
        !g_outer_frame_timing.frame_ended ||
        g_outer_frame_timing.end_frame_return <= 0 ||
        !g_outer_frame_timing.post_engine_surface_depths[
            static_cast<std::size_t>(PostEngineSurfaceTimingKind::proxy)] ||
        !g_outer_frame_timing.post_engine_surface_depths[
            static_cast<std::size_t>(PostEngineSurfaceTimingKind::flush)])
        return;
    ++g_outer_frame_timing.post_engine_surface_material_group_full_scans;
}

bool bridge_take_outer_frame_timing(
    std::int64_t present_entry,
    OuterFrameTimingSnapshot& snapshot) noexcept {
    snapshot = {};
    if (!outer_frame_timing_active()) return false;
    const auto state = g_outer_frame_timing;
    const bool visual_profile_complete =
        !state.count_time_profile_active &&
        g_visual_unit_update_profile_phase ==
            VisualUnitUpdateProfilePhase::inactive &&
        g_visual_unit_update_profile_phase_begin == 0 &&
        g_visual_unit_update_finish_sample == nullptr &&
        !g_native_tick_original_profile_active &&
        g_native_tick_owned_depth == 0 &&
        g_native_tick_owned_pause_depth == 0 &&
        g_native_tick_owned_current == NativeTickOwnedCallback::count;
    g_outer_frame_timing = {};
    visual_unit_update_profile_reset();
    g_native_tick_original_profile_active = false;
    g_native_tick_owned_current = NativeTickOwnedCallback::count;
    g_native_tick_owned_begin = 0;
    g_native_tick_owned_depth = 0;
    g_native_tick_owned_pause_depth = 0;
    snapshot.bridge_frame = state.bridge_frame;
    snapshot.count_time_ticks = state.count_time_ticks;
    snapshot.interface_on_idle_ticks = state.interface_on_idle_ticks;
    snapshot.message_handling_ticks = state.message_handling_ticks;
    snapshot.visual_unit_update_original_ticks =
        state.visual_unit_update_original_ticks;
    snapshot.visual_unit_update_finish_ticks =
        state.visual_unit_update_finish_ticks;
    snapshot.visual_unit_update_finish_appearance_ticks =
        state.visual_unit_update_finish_appearance_ticks;
    snapshot.visual_unit_update_finish_selected_clip_ticks =
        state.visual_unit_update_finish_selected_clip_ticks;
    snapshot.visual_unit_update_finish_outer_unit_values_ticks =
        state.visual_unit_update_finish_outer_unit_values_ticks;
    snapshot.native_lifecycle_tick_original_ticks =
        state.native_lifecycle_tick_original_ticks;
    snapshot.native_tick_unit_original_ticks =
        state.native_tick_unit_original_ticks;
    snapshot.native_tick_unit_finish_ticks =
        state.native_tick_unit_finish_ticks;
    snapshot.native_tick_owned_callbacks = state.native_tick_owned_callbacks;
    snapshot.visual_events = state.visual_events;
    snapshot.visual_event_count = state.visual_event_count;
    snapshot.visual_event_overflow = state.visual_event_overflow;
    snapshot.direct_calls = state.direct_calls;
    snapshot.visual_world_tick_ticks = state.visual_world_tick_ticks;
    snapshot.visual_world_tick_objects_ticks =
        state.visual_world_tick_objects_ticks;
    snapshot.visual_world_tick_terrain_ticks =
        state.visual_world_tick_terrain_ticks;
    snapshot.visual_world_tick_bridge_forced_ticks =
        state.visual_world_tick_bridge_forced_ticks;
    snapshot.visual_world_tick_commit_ticks =
        state.visual_world_tick_commit_ticks;
    snapshot.post_engine_surface_proxy_ticks =
        state.post_engine_surface_proxy_ticks;
    snapshot.post_engine_surface_flush_ticks =
        state.post_engine_surface_flush_ticks;
    snapshot.post_engine_surface_cpu_rect_ticks =
        state.post_engine_surface_cpu_rect_ticks;
    snapshot.post_engine_completed_surface_ticks =
        state.post_engine_completed_surface_ticks;
    snapshot.count_time_calls = state.count_time_calls;
    snapshot.interface_on_idle_calls = state.interface_on_idle_calls;
    snapshot.message_handler_calls = state.message_handler_calls;
    snapshot.visual_unit_update_original_calls =
        state.visual_unit_update_original_calls;
    snapshot.visual_unit_update_finish_calls =
        state.visual_unit_update_finish_calls;
    snapshot.visual_unit_update_finish_appearance_calls =
        state.visual_unit_update_finish_appearance_calls;
    snapshot.visual_unit_update_finish_selected_clip_calls =
        state.visual_unit_update_finish_selected_clip_calls;
    snapshot.visual_unit_update_finish_outer_unit_values_calls =
        state.visual_unit_update_finish_outer_unit_values_calls;
    snapshot.native_lifecycle_tick_original_calls =
        state.native_lifecycle_tick_original_calls;
    snapshot.visual_world_tick_calls = state.visual_world_tick_calls;
    snapshot.visual_world_tick_manager_objects =
        state.visual_world_tick_manager_objects;
    snapshot.visual_world_tick_terrain_layers =
        state.visual_world_tick_terrain_layers;
    snapshot.visual_world_tick_terrain_noise_values =
        state.visual_world_tick_terrain_noise_values;
    snapshot.visual_world_tick_bridge_planes =
        state.visual_world_tick_bridge_planes;
    snapshot.visual_world_tick_forced_ids =
        state.visual_world_tick_forced_ids;
    snapshot.visual_world_tick_committed_entities =
        state.visual_world_tick_committed_entities;
    snapshot.post_engine_surface_proxy_calls =
        state.post_engine_surface_proxy_calls;
    snapshot.post_engine_surface_flush_calls =
        state.post_engine_surface_flush_calls;
    snapshot.post_engine_surface_cpu_rect_calls =
        state.post_engine_surface_cpu_rect_calls;
    snapshot.post_engine_surface_cpu_rect_pixels =
        state.post_engine_surface_cpu_rect_pixels;
    snapshot.post_engine_completed_surface_calls =
        state.post_engine_completed_surface_calls;
    snapshot.post_engine_completed_surface_bytes =
        state.post_engine_completed_surface_bytes;
    snapshot.post_engine_surface_material_group_full_scans =
        state.post_engine_surface_material_group_full_scans;
    snapshot.slowest_visual_unit_update_finish =
        state.slowest_visual_unit_update_finish;
    if (state.end_frame_return > 0 && present_entry >= state.end_frame_return)
        snapshot.post_end_frame_to_present_entry_ticks =
            present_entry - state.end_frame_return;
    else
        snapshot.post_end_frame_to_present_entry_ticks = 0;
    const auto world_child_ticks = state.visual_world_tick_objects_ticks +
        state.visual_world_tick_terrain_ticks +
        state.visual_world_tick_bridge_forced_ticks +
        state.visual_world_tick_commit_ticks;
    const auto surface_child_ticks = state.post_engine_surface_flush_ticks +
        state.post_engine_surface_cpu_rect_ticks +
        state.post_engine_completed_surface_ticks;
    snapshot.fresh = !state.invalid && visual_profile_complete &&
        state.count_time_begin == 0 &&
        g_outer_direct_timing_depth == 0 &&
        state.visual_world_tick_depth == 0 &&
        std::all_of(state.visual_world_tick_child_depths.begin(),
            state.visual_world_tick_child_depths.end(),
            [](std::uint32_t depth) { return depth == 0; }) &&
        std::all_of(state.post_engine_surface_depths.begin(),
            state.post_engine_surface_depths.end(),
            [](std::uint32_t depth) { return depth == 0; }) &&
        world_child_ticks >= 0 &&
        world_child_ticks <= state.visual_world_tick_ticks &&
        surface_child_ticks >= 0 &&
        surface_child_ticks <= state.post_engine_surface_proxy_ticks &&
        state.frame_begun && state.frame_ended && state.bridge_frame != 0 &&
        state.end_frame_return > 0 && present_entry >= state.end_frame_return &&
        state.count_time_calls == state.interface_on_idle_calls &&
        state.count_time_calls != 0;
    return true;
}

bool bridge_outer_frame_timing_matches(
    const OuterFrameTimingSnapshot& snapshot,
    const BridgeProfileSnapshot* bridge) noexcept {
    return snapshot.fresh && bridge && bridge->frame != 0 &&
        snapshot.bridge_frame == bridge->frame;
}

void bridge_profile_api_entry(const char* kind, const void* caller) {
    if (!bridge_profile_enabled()) return;
    const auto now = bridge_now();
    auto caller_rva = EngineBridge::instance().image_rva(caller);
    if (!caller_rva) caller_rva = g_semantic.caller_rva;
    if (g_bridge_sample.active && g_previous_api_entry > 0 && now >= g_previous_api_entry) {
        BridgeFrameSample::ApiGap candidate{};
        candidate.ticks = now - g_previous_api_entry;
        if (!caller_rva && candidate.ticks * 1000 >= bridge_frequency() / 4) {
            void* frames[8]{};
            const USHORT count = CaptureStackBackTrace(0, static_cast<DWORD>(std::size(frames)),
                                                       frames, nullptr);
            for (USHORT index = 0; index < count && !caller_rva; ++index)
                caller_rva = EngineBridge::instance().image_rva(frames[index]);
        }
        candidate.from_kind = g_previous_api_kind;
        candidate.to_kind = kind ? kind : "unknown";
        candidate.from_rva = g_previous_api_rva;
        candidate.to_rva = caller_rva;
        auto& gaps = g_bridge_sample.largest_api_gaps;
        auto position = gaps.begin();
        while (position != gaps.end() && position->ticks >= candidate.ticks) ++position;
        if (position != gaps.end()) {
            std::move_backward(position, gaps.end() - 1, gaps.end());
            *position = candidate;
        }
    }
    g_previous_api_entry = now;
    g_previous_api_kind = kind ? kind : "unknown";
    g_previous_api_rva = caller_rva;
}

SceneRendererTimingToken bridge_scene_renderer_timing_begin(
    SceneRendererTimingKind kind) noexcept {
    SceneRendererTimingToken token{};
    if (!g_scene_partition.active || !g_bridge_sample.active) return token;
    if (g_scene_partition.renderer_depth++) g_scene_partition.invalid = true;
    token.begin = bridge_now();
    token.context = static_cast<std::uint8_t>(
        current_scene_partition_context());
    token.kind = kind;
    token.active = token.begin > 0;
    if (!token.active) {
        if (g_scene_partition.renderer_depth)
            --g_scene_partition.renderer_depth;
        g_scene_partition.invalid = true;
    }
    return token;
}

void bridge_scene_renderer_timing_end(
    SceneRendererTimingToken& token) noexcept {
    if (!token.active) return;
    const auto end = bridge_now();
    if (!g_scene_partition.active || !g_bridge_sample.active ||
        !g_scene_partition.renderer_depth || end < token.begin ||
        token.context >= kScenePartitionContextCount) {
        invalidate_scene_partition();
        if (g_scene_partition.renderer_depth)
            --g_scene_partition.renderer_depth;
        token = {};
        return;
    }
    --g_scene_partition.renderer_depth;
    const auto context = static_cast<ScenePartitionContext>(token.context);
    if (current_scene_partition_context() != context)
        g_scene_partition.invalid = true;
    auto& values = token.kind == SceneRendererTimingKind::native_flush
        ? g_scene_partition.native_flush_ticks
        : g_scene_partition.ui_flush_ticks;
    const auto elapsed = end - token.begin;
    if (values[token.context] < 0 || elapsed < 0 ||
        values[token.context] >
            (std::numeric_limits<std::int64_t>::max)() - elapsed)
        g_scene_partition.invalid = true;
    else
        values[token.context] += elapsed;
    token = {};
}

SceneQueueTimingToken bridge_scene_queue_timing_begin() noexcept {
    SceneQueueTimingToken token{};
    if (!g_scene_partition.active || !g_bridge_sample.active) return token;
    if (g_scene_partition.queue_depth) {
        g_scene_partition.invalid = true;
        return token;
    }
    token.begin = bridge_now();
    token.native_ticks_at_begin = scene_partition_renderer_total(
        SceneRendererTimingKind::native_flush);
    token.ui_ticks_at_begin = scene_partition_renderer_total(
        SceneRendererTimingKind::ui_flush);
    token.context = static_cast<std::uint8_t>(
        current_scene_partition_context());
    token.active = token.begin > 0;
    if (token.active) {
        g_scene_partition.queue_depth = 1;
    } else {
        g_scene_partition.invalid = true;
    }
    return token;
}

void bridge_scene_queue_timing_end(SceneQueueTimingToken& token) noexcept {
    if (!token.active) return;
    const auto end = bridge_now();
    const auto native_now = scene_partition_renderer_total(
        SceneRendererTimingKind::native_flush);
    const auto ui_now = scene_partition_renderer_total(
        SceneRendererTimingKind::ui_flush);
    if (!g_scene_partition.active || !g_bridge_sample.active ||
        g_scene_partition.queue_depth != 1 || end < token.begin ||
        native_now < token.native_ticks_at_begin ||
        ui_now < token.ui_ticks_at_begin ||
        token.context >= kScenePartitionContextCount) {
        invalidate_scene_partition();
        g_scene_partition.queue_depth = 0;
        token = {};
        return;
    }
    const auto native_ticks = native_now - token.native_ticks_at_begin;
    const auto ui_ticks = ui_now - token.ui_ticks_at_begin;
    const auto total_ticks = end - token.begin;
    if (total_ticks < native_ticks || total_ticks - native_ticks < ui_ticks) {
        g_scene_partition.invalid = true;
    } else {
        const auto context = static_cast<ScenePartitionContext>(token.context);
        if (current_scene_partition_context() != context)
            g_scene_partition.invalid = true;
        const auto packet_ticks = total_ticks - native_ticks - ui_ticks;
        auto& accumulated = g_scene_partition.packet_ticks[token.context];
        if (accumulated < 0 || packet_ticks < 0 || accumulated >
                (std::numeric_limits<std::int64_t>::max)() - packet_ticks) {
            g_scene_partition.invalid = true;
        } else {
            accumulated += packet_ticks;
            ++g_bridge_sample.scene_partition_queue_calls;
        }
    }
    g_scene_partition.queue_depth = 0;
    token = {};
}

