void bridge_trace_input_focus(HWND window, const char* phase, UINT message,
                              WPARAM wparam, int overlay_mode) noexcept {
    if (!input_focus_trace_enabled() || !g_owned_cursor_installed) return;
    const ULONGLONG now = GetTickCount64();
    // One snapshot per second while presenting, plus every focus message.
    // Mouse normalization events above are recorded independently.
    static ULONGLONG last_frame = 0;
    if (!message && last_frame && now - last_frame < 1000) return;
    if (!message) last_frame = now;
    const auto* image = reinterpret_cast<const std::uint8_t*>(GetModuleHandleW(nullptr));
    const auto owns_call = [image](std::uint32_t rva, const void* hook) {
        std::int32_t relative = 0;
        std::memcpy(&relative, image + rva + 1, sizeof(relative));
        return image[rva] == 0xe8 && image + rva + 5 + relative == hook;
    };
    RECT client{}, clip{};
    const bool client_valid = cursor_confinement_client_rect(window, client);
    const bool clip_valid = GetClipCursor(&clip) != FALSE;
    POINT cursor{};
    const bool position_valid = GetCursorPos(&cursor) && ScreenToClient(window, &cursor);
    OwnedCursorFrame frame{};
    bridge_owned_cursor_frame(frame);
    char detail[640]{};
    std::snprintf(detail, sizeof(detail),
        "ms=%llu thread=%lu phase=%s message=%u wparam=%lu foreground=%d iconic=%d overlay=%d "
        "client_valid=%d client=%ld,%ld,%ld,%ld clip_valid=%d clip=%ld,%ld,%ld,%ld "
        "position_valid=%d os_cursor=%ld,%ld owned_cursor=%ld,%ld visible=%d "
        "cursor_flags=%ld camera_installed=%d,%d,%d camera_live=%d,%d,%d carry=%lld,%lld",
        now, GetCurrentThreadId(), phase, message, static_cast<unsigned long>(wparam),
        GetForegroundWindow() == window, IsIconic(window) != FALSE, overlay_mode,
        client_valid, client.left, client.top, client.right, client.bottom,
        clip_valid, clip.left, clip.top, clip.right, clip.bottom,
        position_valid, cursor.x, cursor.y, frame.x + frame.hot_x, frame.y + frame.hot_y,
        frame.visible, InterlockedCompareExchange(&g_input_trace_cursor_flags, 0, 0),
        g_camera_mouse_yaw_installed, g_camera_mouse_pitch_installed,
        g_camera_mouse_normalize_installed,
        owns_call(kCameraMouseYawCallRva, reinterpret_cast<const void*>(&hook_camera_mouse_yaw)),
        owns_call(kCameraMousePitchCallRva, reinterpret_cast<const void*>(&hook_camera_mouse_pitch)),
        owns_call(kCameraMouseNormalizeCallRva, reinterpret_cast<const void*>(&hook_camera_mouse_normalize)),
        g_camera_mouse_carry.x, g_camera_mouse_carry.y);
    append_bridge_event("input_focus", detail, true);
}

